export const ASSETS = {
  "pet.css": { type: "text/css; charset=utf-8", body: "/* オーバーレイなので背景は必ず完全透明。body に色を置いた瞬間に四角が見える。 */\nhtml,\nbody {\n  margin: 0;\n  height: 100%;\n  background: transparent;\n  overflow: hidden;\n  user-select: none;\n  cursor: default;\n  font-family: -apple-system, BlinkMacSystemFont, 'Hiragino Sans', 'Noto Sans JP', sans-serif;\n}\n\n#stage {\n  position: relative;\n  width: 200px;\n  height: 200px;\n  /* 系統が決まるまでは無彩色寄り。決まると色がつく。 */\n  --hue: 220;\n  --sat: 12%;\n  --body: hsl(var(--hue) var(--sat) 62%);\n  --body-dark: hsl(var(--hue) var(--sat) 46%);\n  --ink: hsl(var(--hue) 30% 18%);\n  --scale: 1;\n}\n\n#pet {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n}\n\n/* 拡大の基点は足元。上に伸びるので、レベルが上がっても接地位置がぶれない。 */\n#creature {\n  transform-origin: 100px 166px;\n  transform: scale(var(--scale));\n  animation: bob 2.8s ease-in-out infinite;\n}\n\n#body {\n  fill: var(--body);\n  stroke: var(--body-dark);\n  stroke-width: 3.5;\n  filter: drop-shadow(0 4px 10px hsl(var(--hue) 40% 20% / 0.35));\n}\n\n/*\n * 体の上のつや。**白を薄く 1 枚**だけ。系統色に寄せると、色が変わるたびに\n * つやの見え方が変わって落ち着かない ── 光は色を持たない。\n */\n#sheen {\n  fill: #fff;\n  opacity: 0.16;\n  pointer-events: none;\n}\n\n#shadow {\n  fill: hsl(0 0% 0% / 0.22);\n  filter: blur(3px);\n}\n\n.eyeball {\n  fill: #fff;\n}\n\n/*\n * 瞳の光。**これ 1 個で顔つきが変わる** ── 真っ黒のままだと、どれだけ形を\n * 丸くしても「点」にしか見えない。\n */\n.glint {\n  fill: #fff;\n  opacity: 0.92;\n  pointer-events: none;\n}\n\n/*\n * 頬の赤み。**系統色に寄せる**ので、系統が決まるまではほとんど出ない\n * （無彩色の子に頬紅だけ乗ると浮く）。顔の形には触らない ── 目つきと\n * 口元は型が決めるもの（DESIGN.md §8c）。\n */\n#blush ellipse {\n  fill: hsl(var(--hue) var(--sat) 48%);\n  opacity: 0.3;\n}\n.pupil {\n  fill: var(--ink);\n  transition: transform 0.18s ease-out;\n}\n.lid {\n  fill: none;\n  stroke: var(--ink);\n  stroke-width: 3.5;\n  stroke-linecap: round;\n  opacity: 0;\n}\n\n#mouth {\n  fill: none;\n  stroke: var(--ink);\n  stroke-width: 3.5;\n  stroke-linecap: round;\n}\n\n#antenna path {\n  fill: none;\n  stroke: var(--body-dark);\n  stroke-width: 4;\n  stroke-linecap: round;\n}\n#antenna circle {\n  fill: var(--body-dark);\n}\n#antenna,\n#crown,\n#aura {\n  opacity: 0;\n  transition: opacity 0.4s ease;\n}\n#stage.has-antenna #antenna,\n#stage.has-crown #crown,\n#stage.has-aura #aura {\n  opacity: 1;\n}\n\n#crown path {\n  fill: hsl(45 90% 60%);\n  stroke: hsl(38 70% 38%);\n  stroke-width: 2.5;\n  stroke-linejoin: round;\n}\n\n/*\n * オーラは体の奥に回る。**胴体と一緒に大きくする** ── 前は `#creature` の外に\n * あるせいで拡大に付いてこず、そのぶん「どの大きさでも body の外に出る」\n * 半径（74x58）で描いてあった。結果、**Lv が上がるほど上は body に食い込み、\n * 横と下だけ大きく空く**（スマホだと 200px の枠いっぱいの輪っかになって、\n * 相棒より輪のほうが目立っていた）。\n *\n * 拡大は「まとまり」に、回転は「楕円」に掛ける ── transform は 1 つしか\n * 持てないので、同じ要素に両方書くと後から当たったほうだけが残る。\n */\n#aura {\n  transform-origin: 100px 166px; /* creature と同じ足元 */\n  transform: scale(var(--scale));\n}\n\n#aura ellipse {\n  fill: none;\n  stroke: var(--body);\n  stroke-width: 2;\n  stroke-dasharray: 6 14;\n  transform-origin: 100px 122px;\n  animation: spin 9s linear infinite;\n  opacity: 0.55;\n}\n\n/*\n * **点線の輪は 1 本だけ。** 守りの装備（ward）も点線の輪を 2 本回すので、\n * オーラと同時に出ると輪が 3 本重なって、相棒より輪のほうが大きく見える\n * ── スマホだと 200px の枠が丸ごと輪で埋まっていた。装備のほうが\n * 「なぜ出ているか」を説明できるので、素のオーラを引っ込める。\n */\n/*\n * 🔴 **素のオーラも出さない。** 上と同じ理由で、点線の輪は額縁に見える。\n * 2026-08-16、実機（Lv16）で「枠線の輪」と呼ばれた。\n * Lv15 以上でいつも出るものだったので、いちばん長く目に入っていた。\n *\n * ⚠️ 絵（[pet-svg.js]）の #aura は残してある。**戻したくなったらここを外すだけ**で、\n *    絵を描き直す必要は無い。\n */\n#stage.has-aura #aura,\n#stage.gw-def-ward #aura {\n  opacity: 0;\n}\n\n/* ---- 吹き出し ----\n   真上ではなく左上に置く。真上だと冠や触角と必ずぶつかる。 */\n#bubble {\n  position: absolute;\n  top: 8px;\n  left: 6px;\n  transform-origin: bottom left;\n  transform: scale(0.7);\n  padding: 4px 12px;\n  border-radius: 12px;\n  background: hsl(0 0% 100% / 0.92);\n  color: hsl(220 20% 22%);\n  font-size: 15px;\n  font-weight: 700;\n  line-height: 1.4;\n  letter-spacing: 0.06em;\n  box-shadow: 0 3px 10px hsl(220 40% 20% / 0.28);\n  opacity: 0;\n  transition: opacity 0.2s ease, transform 0.2s ease;\n  white-space: nowrap;\n}\n#stage.show-bubble #bubble {\n  opacity: 1;\n  transform: scale(1);\n}\n\n/* 実績とレベルアップの瞬間だけ。系統色で光らせて、数秒で普通の吹き出しに戻る。 */\n#stage.bubble-loud #bubble {\n  background: var(--body);\n  color: hsl(var(--hue) 40% 14%);\n  box-shadow: 0 0 14px hsl(var(--hue) 80% 60% / 0.55);\n}\n\n/* ---- レベル表示 ---- */\n#badge {\n  position: absolute;\n  bottom: 2px;\n  left: 50%;\n  transform: translateX(-50%);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 11px;\n  font-weight: 700;\n  white-space: nowrap;\n  color: hsl(0 0% 100% / 0.92);\n  text-shadow: 0 1px 3px hsl(0 0% 0% / 0.65);\n  opacity: 0.55;\n  transition: opacity 0.25s ease;\n}\n#stage.mood-working #badge,\n#stage.mood-calling #badge {\n  opacity: 1;\n}\n\n#bar {\n  width: 46px;\n  height: 4px;\n  border-radius: 2px;\n  background: hsl(0 0% 100% / 0.28);\n  overflow: hidden;\n}\n#bar-fill {\n  display: block;\n  height: 100%;\n  width: 0%;\n  border-radius: 2px;\n  background: var(--body);\n  transition: width 0.5s ease;\n}\n\n/* ---- 気分ごとの動き ---- */\n/*\n * 浮き沈み。**上下だけだと「動いている絵」で、生き物には見えない。**\n * 沈んだところで少し潰れて、上がりきったところで少し伸びる（squash &\n * stretch）── 幅と高さを 1.5% 動かすだけで、同じ動きが呼吸に見える。\n */\n@keyframes bob {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0) scale(1.015, 0.985);\n  }\n  50% {\n    transform: scale(var(--scale)) translateY(-4px) scale(0.99, 1.01);\n  }\n}\n\n@keyframes hop {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n  30% {\n    transform: scale(var(--scale)) translateY(-14px);\n  }\n  55% {\n    transform: scale(var(--scale)) translateY(0) scaleY(0.92);\n  }\n  75% {\n    transform: scale(var(--scale)) translateY(-4px);\n  }\n}\n\n@keyframes breathe {\n  0%,\n  100% {\n    transform: scale(var(--scale)) scaleY(0.94) translateY(6px);\n  }\n  50% {\n    transform: scale(var(--scale)) scaleY(0.99) translateY(4px);\n  }\n}\n\n@keyframes spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n#stage.mood-working #creature {\n  animation: hop 0.62s ease-in-out infinite;\n}\n#stage.mood-thinking #creature {\n  animation: bob 1.5s ease-in-out infinite;\n}\n#stage.mood-calling #creature {\n  animation: hop 0.9s ease-in-out infinite;\n}\n#stage.mood-sleeping #creature {\n  animation: breathe 4.2s ease-in-out infinite;\n}\n/* 寝ているときは目を閉じる */\n#stage.mood-sleeping .lid {\n  opacity: 1;\n}\n#stage.mood-sleeping .pupil,\n#stage.mood-sleeping .eyeball,\n#stage.mood-sleeping .glint {\n  opacity: 0;\n}\n#stage.mood-sleeping #badge {\n  opacity: 0.2;\n}\n\n/* ── リズム（persona.js の 5 軸目）で息づかいの速さが変わる ─────────\n   凪 はゆったり、波 はせかせか。**気分の指定より後ろ・しぐさより前に置く**\n   ── 気分が決めた動き方の「速さだけ」を上書きして、しぐさの最中は\n   しぐさ側の指定（animation の一括指定）がまるごと勝つ。 */\n#stage.r-calm #creature {\n  animation-duration: 3.6s;\n}\n#stage.r-wave #creature {\n  animation-duration: 1.9s;\n}\n\n/* まばたき */\n#stage.blink .lid {\n  opacity: 1;\n}\n#stage.blink .pupil,\n#stage.blink .eyeball,\n#stage.blink .glint {\n  opacity: 0;\n}\n\n/* ---- 使い込み ------------------------------------------------------\n   **一緒にいた長さが、そのまま傷になる。** 性能には 1 も効かない ──\n   歴戦の証であって、罰ではない（放置で弱らせない。DESIGN.md §3）。 */\n\n#patina .scar,\n#patina .chip {\n  opacity: 0;\n  transition: opacity 1.2s ease;\n}\n\n#patina .scar {\n  fill: none;\n  stroke: var(--body-dark);\n  stroke-width: 2.5;\n  stroke-linecap: round;\n  opacity: 0;\n}\n\n#patina .chip {\n  fill: hsl(var(--hue) var(--sat) 40%);\n}\n\n/* 30 日 ── 使い込まれてきた */\n#stage.pt-1 #scar-1,\n#stage.pt-2 #scar-1,\n#stage.pt-3 #scar-1 {\n  opacity: 0.45;\n}\n\n/* 120 日 ── 年季が入った */\n#stage.pt-2 #scar-2,\n#stage.pt-3 #scar-2,\n#stage.pt-2 #scar-3,\n#stage.pt-3 #scar-3 {\n  opacity: 0.4;\n}\n\n/* 1 年 ── 満身創痍。縁も少し欠ける */\n#stage.pt-3 #scar-4,\n#stage.pt-3 #scar-5 {\n  opacity: 0.35;\n}\n#stage.pt-3 #chip-1,\n#stage.pt-3 #chip-2 {\n  opacity: 0.8;\n}\n\n/*\n * 装備も一緒に古びる。**光沢だけ落として、色と大きさは変えない**\n * ── 弱くなったように見せない（実際に弱くなっていない）。\n */\n#stage.pt-2 .gear-atk .edge,\n#stage.pt-2 .gear-def .plate {\n  filter: saturate(0.85);\n}\n#stage.pt-3 .gear-atk .edge,\n#stage.pt-3 .gear-def .plate {\n  filter: saturate(0.7);\n  stroke-dasharray: 22 3;\n}\n\n/* ---- 顔まわりの小物 -------------------------------------------------\n   **どれも作業ログから生えている**（買えるスキンとは出どころが違うので、\n   顔に掛かってよい。DESIGN.md §8c）。既定では全部消えている。 */\n\n#wear .worn {\n  opacity: 0;\n  transition: opacity 0.6s ease;\n}\n\n#stage.ac-stubble #ac-stubble,\n#stage.ac-moustache #ac-moustache,\n#stage.ac-beard #ac-beard,\n#stage.ac-glasses #ac-glasses,\n#stage.ac-shades #ac-shades,\n#stage.ac-scarf #ac-scarf,\n#stage.ac-bandage #ac-bandage,\n#stage.ac-earring #ac-earring {\n  opacity: 1;\n}\n\n/* ひげは体より少し濃いだけ。別の色を置くと、貼り付けたように見える */\n#wear .hair {\n  fill: var(--body-dark);\n  opacity: 0.85;\n}\n\n#wear .rim {\n  fill: none;\n  stroke: var(--ink);\n  stroke-width: 3;\n  stroke-linecap: round;\n}\n\n/*\n * サングラスは**中を透かさない。掛けている間は目を消す。**\n *\n * 前は 0.72 で透かしていた（目つきは型が決めるものなので、塗り潰すと\n * この子が誰なのか顔から消える、という理屈）。**が、実際に描くと汚かった**\n * ── レンズは角の立った形、目は半径 9 の丸なので、下と横から白目と瞳が\n * はみ出して、掛けそこねているようにしか見えない。大きさを合わせにいっても\n * 丸と角では必ずどこかが出る。\n *\n * 消すのは `.eye` の**まとまりごと**。中の `.eyeball` / `.pupil` を個別に\n * 消す書き方（まばたき・寝るときと同じ）にすると、しぐさのアニメーションが\n * 後から opacity を戻してきて、サングラスの下で目が動く。\n */\n#stage.ac-shades #face .eye {\n  opacity: 0;\n}\n\n#wear #ac-shades .lens {\n  fill: hsl(var(--hue) 28% 11%);\n}\n\n/* 斜めの光。無いと、顔に黒い穴が 2 つ空いているように見える（`.glint` と同じ） */\n#wear #ac-shades .shine {\n  fill: #fff;\n  opacity: 0.14;\n}\n\n#wear #ac-scarf .cloth {\n  fill: hsl(var(--hue) 45% 46%);\n  stroke: hsl(var(--hue) 45% 34%);\n  stroke-width: 2;\n}\n\n#wear #ac-bandage .patch {\n  fill: #f2e9dc;\n  stroke: #cbbfae;\n  stroke-width: 1.5;\n}\n\n/* ---- ケガ ----------------------------------------------------------\n   **直前の一戦に負けたときだけ、1 時間。**（appearance.js の hurtFor）\n\n   何もしなくても勝手に治る ── 手当てのボタンは無いし、そのあいだ\n   弱ってもいない（数字には 1 も効かない）。世話をさせないための線。 */\n\n#hurt .wound {\n  opacity: 0;\n  transition: opacity 1.5s ease;\n}\n\n#stage.hurt-2 #hurt-deep,\n#stage.hurt-1 #hurt-mild {\n  opacity: 1;\n}\n\n#hurt .plaster {\n  fill: #f2e9dc;\n  stroke: #cbbfae;\n  stroke-width: 1.5;\n}\n#hurt .plaster-cross {\n  fill: none;\n  stroke: #cbbfae;\n  stroke-width: 1.5;\n  stroke-linecap: round;\n}\n/* 擦り傷。使い込みの古傷（#patina）より赤みを持たせて、別物だと分かるように */\n#hurt .graze {\n  fill: none;\n  stroke: hsl(6 55% 52%);\n  stroke-width: 2.5;\n  stroke-linecap: round;\n  opacity: 0.7;\n}\n\n#wear #ac-earring .stud {\n  fill: hsl(45 80% 62%);\n}\n#wear #ac-earring .wire {\n  fill: none;\n  stroke: hsl(45 60% 52%);\n  stroke-width: 2.5;\n  stroke-linecap: round;\n}\n\n/* ---- 装備と、育ちの段 ------------------------------------------------\n   **既定では全部消えている。** appearance.js が付けたクラスに当たったものだけ出る。\n   絵を増やさずに数を出すための重ね方は pet-svg.js の見出しに書いてある。\n\n   色は**位**（コモン〜レジェンド）で決める。系統色（--hue）には寄せない\n   ── 寄せると、位の色が人によって別物になる（スマホ側と同じ決まり）。 */\n\n.gear-atk,\n.gear-def,\n.gear-spd,\n#growth .grow {\n  opacity: 0;\n  transition: opacity 0.5s ease;\n}\n\n/* 位ごとの色。0〜4 で明るくなる */\n#stage {\n  --gear-atk: 210 8% 62%;\n  --gear-def: 210 8% 62%;\n  --gear-spd: 210 8% 62%;\n}\n#stage.gr-atk-uncommon {\n  --gear-atk: 145 45% 60%;\n}\n#stage.gr-atk-rare {\n  --gear-atk: 210 70% 66%;\n}\n#stage.gr-atk-mystic {\n  --gear-atk: 285 62% 70%;\n}\n#stage.gr-atk-legend {\n  --gear-atk: 42 85% 62%;\n}\n#stage.gr-def-uncommon {\n  --gear-def: 145 45% 60%;\n}\n#stage.gr-def-rare {\n  --gear-def: 210 70% 66%;\n}\n#stage.gr-def-mystic {\n  --gear-def: 285 62% 70%;\n}\n#stage.gr-def-legend {\n  --gear-def: 42 85% 62%;\n}\n#stage.gr-spd-uncommon {\n  --gear-spd: 145 45% 60%;\n}\n#stage.gr-spd-rare {\n  --gear-spd: 210 70% 66%;\n}\n#stage.gr-spd-mystic {\n  --gear-spd: 285 62% 70%;\n}\n#stage.gr-spd-legend {\n  --gear-spd: 42 85% 62%;\n}\n\n/* 出す ── 持っている型のものだけ */\n#stage.gw-atk-blade #gw-blade,\n#stage.gw-atk-axe #gw-axe,\n#stage.gw-atk-hammer #gw-hammer,\n#stage.gw-atk-lance #gw-lance,\n#stage.gw-atk-bow #gw-bow,\n#stage.gw-atk-whip #gw-whip,\n#stage.gw-def-shield #gw-shield,\n#stage.gw-def-plate #gw-plate,\n#stage.gw-def-cloak #gw-cloak,\n#stage.gw-def-helm #gw-helm,\n#stage.gw-def-ward #gw-ward,\n#stage.gw-spd-dash #gw-dash,\n#stage.gw-spd-wing #gw-wing,\n#stage.gw-spd-orb #gw-orb,\n#stage.gw-spd-lens #gw-lens {\n  opacity: 1;\n}\n\n.gear-atk .edge {\n  fill: hsl(var(--gear-atk));\n  stroke: hsl(var(--gear-atk) / 0.5);\n  stroke-width: 2;\n}\n.gear-atk .grip,\n.gear-atk .guard {\n  fill: none;\n  stroke: hsl(var(--gear-atk));\n  stroke-width: 5;\n  stroke-linecap: round;\n}\n#gw-bow .edge,\n#gw-whip .edge {\n  fill: none;\n  stroke: hsl(var(--gear-atk));\n  stroke-width: 4;\n  stroke-linecap: round;\n}\n#gw-bow .grip {\n  stroke-width: 2;\n  stroke: hsl(var(--gear-atk) / 0.6);\n}\n\n.gear-def .plate {\n  fill: hsl(var(--gear-def));\n  stroke: hsl(var(--gear-def) / 0.6);\n  stroke-width: 2.5;\n}\n.gear-def .trim {\n  fill: none;\n  stroke: hsl(var(--gear-def) / 0.55);\n  stroke-width: 2.5;\n  stroke-linecap: round;\n}\n/*\n * 🔴 **輪郭で囲まない。** 点線の輪は「守られている」ではなく**枠線**に見える。\n *\n * 実機（2026-08-16・Lv16）で、相棒より輪のほうが目に入っていた。素のオーラを\n * 引っ込めても（[#stage.gw-def-ward #aura]）、ward 自身の輪が2本残るので同じことが起きる。\n * スマホの 200px の枠では、体を囲む線はどうやっても額縁になる。\n *\n * 囲うのをやめて、**体の後ろに柔らかい膜を敷く**形にした。守りは「囲い」ではなく\n * 「厚み」で見せる。回転も外した ── 動くものが増えるほど、相棒の表情から目が逸れる。\n */\n#gw-ward .ring {\n  fill: hsl(var(--gear-def) / 0.16);\n  stroke: none;\n}\n/* 2本目は輪だったもの。膜を1枚にするので出さない */\n#gw-ward .ring2 {\n  display: none;\n}\n\n@keyframes ward-turn {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n/* 置いていった風の筋。手前ほど濃く、後ろほど薄い */\n.gear-spd .streak {\n  fill: none;\n  stroke: hsl(var(--gear-spd) / 0.75);\n  stroke-width: 4;\n  stroke-linecap: round;\n  animation: streak-run 1.6s ease-in-out infinite;\n}\n.gear-spd .streak:nth-child(2) {\n  animation-delay: -0.35s;\n  opacity: 0.8;\n}\n.gear-spd .streak:nth-child(3) {\n  animation-delay: -0.7s;\n  opacity: 0.6;\n}\n\n@keyframes streak-run {\n  0%,\n  100% {\n    transform: translateX(0);\n    opacity: 0.35;\n  }\n  40% {\n    transform: translateX(-7px);\n    opacity: 0.9;\n  }\n}\n.gear-spd .feather {\n  fill: hsl(var(--gear-spd));\n  stroke: hsl(var(--gear-spd) / 0.7);\n  stroke-width: 2;\n}\n.gear-spd .orb,\n.gear-spd .orb2 {\n  fill: hsl(var(--gear-spd) / 0.9);\n  animation: orb-drift 4.5s ease-in-out infinite;\n}\n.gear-spd .orb2 {\n  animation-delay: -2.2s;\n}\n#gw-lens .glass {\n  fill: hsl(var(--gear-spd) / 0.25);\n  stroke: hsl(var(--gear-spd));\n  stroke-width: 3;\n}\n#gw-lens .grip {\n  fill: none;\n  stroke: hsl(var(--gear-spd));\n  stroke-width: 4;\n  stroke-linecap: round;\n}\n\n@keyframes orb-drift {\n  0%,\n  100% {\n    transform: translateY(0);\n  }\n  50% {\n    transform: translateY(-6px);\n  }\n}\n\n/* 育ちの段。**節目は実績と同じ位置**（Lv30 熟練で角、Lv50 達人で尾…） */\n#stage.lk-horns #lk-horns,\n#stage.lk-tail #lk-tail,\n#stage.lk-halo #lk-halo,\n#stage.lk-sigil #lk-sigil {\n  opacity: 1;\n}\n\n#growth #lk-horns path {\n  fill: var(--body-dark);\n}\n#growth #lk-tail path {\n  fill: none;\n  stroke: var(--body-dark);\n  stroke-width: 7;\n  stroke-linecap: round;\n}\n#growth #lk-halo ellipse {\n  fill: none;\n  stroke: hsl(var(--hue) 60% 60% / 0.3);\n  stroke-width: 2;\n  stroke-dasharray: 2 10;\n  animation: ward-turn 40s linear infinite;\n  transform-box: fill-box;\n  transform-origin: center;\n}\n#growth #lk-sigil path {\n  fill: hsl(45 85% 66%);\n  animation: sigil-pulse 3.4s ease-in-out infinite;\n  transform-box: fill-box;\n  transform-origin: center;\n}\n\n@keyframes sigil-pulse {\n  0%,\n  100% {\n    opacity: 0.75;\n    transform: scale(1);\n  }\n  50% {\n    opacity: 1;\n    transform: scale(1.12);\n  }\n}\n\n/* Lv100 から浮く。接地の影も小さくする */\n#stage.lk-float #creature {\n  animation: float-idle 4s ease-in-out infinite;\n}\n#stage.lk-float #shadow {\n  transform: scale(0.82);\n  transform-origin: 100px 168px;\n  opacity: 0.7;\n}\n\n@keyframes float-idle {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(-4px);\n  }\n  50% {\n    transform: scale(var(--scale)) translateY(-11px);\n  }\n}\n\n/* ---- しぐさ ----\n   ときどき勝手に動く。どれを出すかは shared/gestures.js が決める。\n\n   気分のアニメーションと同じ #creature を奪うので、**必ず気分の指定より後ろに置く**\n   （詰まるところ後勝ちで上書きしている。特異度は同じ）。\n   どのキーフレームも scale(var(--scale)) から書き始めること ── 抜くと、\n   しぐさに入った瞬間にレベルぶんの大きさが飛ぶ。 */\n\n@keyframes g-stretch {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n  35% {\n    transform: scale(var(--scale)) translateY(2px) scaleY(0.88) scaleX(1.06);\n  }\n  70% {\n    transform: scale(var(--scale)) translateY(-10px) scaleY(1.14) scaleX(0.94);\n  }\n}\n\n@keyframes g-tilt {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg);\n  }\n  30% {\n    transform: scale(var(--scale)) rotate(-9deg);\n  }\n  65% {\n    transform: scale(var(--scale)) rotate(7deg);\n  }\n}\n\n@keyframes g-bounce {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n  15% {\n    transform: scale(var(--scale)) translateY(-16px);\n  }\n  35% {\n    transform: scale(var(--scale)) translateY(0) scaleY(0.9);\n  }\n  55% {\n    transform: scale(var(--scale)) translateY(-12px);\n  }\n  75% {\n    transform: scale(var(--scale)) translateY(0) scaleY(0.94);\n  }\n}\n\n/* rotateY だと横幅がゼロを通るので、平たくして戻すだけで「回った」に見える */\n@keyframes g-spin {\n  0%,\n  100% {\n    transform: scale(var(--scale)) scaleX(1);\n  }\n  50% {\n    transform: scale(var(--scale)) scaleX(-0.15) translateY(-4px);\n  }\n}\n\n@keyframes g-shiver {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateX(0);\n  }\n  20% {\n    transform: scale(var(--scale)) translateX(-3px);\n  }\n  45% {\n    transform: scale(var(--scale)) translateX(3px);\n  }\n  70% {\n    transform: scale(var(--scale)) translateX(-2px);\n  }\n}\n\n/* 寝返り。転がってから、少しだけ位置がずれて落ち着く */\n@keyframes g-roll {\n  0% {\n    transform: scale(var(--scale)) scaleY(0.94) translateY(6px) rotate(0deg);\n  }\n  45% {\n    transform: scale(var(--scale)) scaleY(0.9) translateY(8px) rotate(-12deg);\n  }\n  100% {\n    transform: scale(var(--scale)) scaleY(0.94) translateY(6px) rotate(0deg);\n  }\n}\n\n@keyframes g-yawn {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n  40% {\n    transform: scale(var(--scale)) translateY(-4px) scaleY(1.06);\n  }\n}\n\n/* レベルアップと実績。跳ねてから胸を張る */\n@keyframes g-levelup {\n  0% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n  20% {\n    transform: scale(var(--scale)) translateY(4px) scaleY(0.85);\n  }\n  45% {\n    transform: scale(var(--scale)) translateY(-26px) scaleY(1.12);\n  }\n  70% {\n    transform: scale(var(--scale)) translateY(0) scaleY(0.94);\n  }\n  85% {\n    transform: scale(var(--scale)) translateY(-8px);\n  }\n  100% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n}\n\n/* 戦闘。構える → 2 回踏み込む → 勝った日は跳ね、負けた日はよろける */\n@keyframes g-battle-win {\n  0%,\n  8% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n  16% {\n    transform: scale(var(--scale)) translateY(6px) scaleY(0.86);\n  }\n  26% {\n    transform: scale(var(--scale)) translateX(18px) rotate(6deg);\n  }\n  36% {\n    transform: scale(var(--scale)) translateX(-4px);\n  }\n  48% {\n    transform: scale(var(--scale)) translateX(20px) rotate(8deg);\n  }\n  58% {\n    transform: scale(var(--scale)) translateX(0);\n  }\n  72% {\n    transform: scale(var(--scale)) translateY(-24px);\n  }\n  84% {\n    transform: scale(var(--scale)) translateY(0) scaleY(0.92);\n  }\n  92% {\n    transform: scale(var(--scale)) translateY(-10px);\n  }\n  100% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n}\n\n@keyframes g-battle-lose {\n  0%,\n  8% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n  16% {\n    transform: scale(var(--scale)) translateY(6px) scaleY(0.86);\n  }\n  26% {\n    transform: scale(var(--scale)) translateX(16px) rotate(5deg);\n  }\n  38% {\n    transform: scale(var(--scale)) translateX(-2px);\n  }\n  50% {\n    transform: scale(var(--scale)) translateX(-16px) rotate(-10deg);\n  }\n  62% {\n    transform: scale(var(--scale)) translateX(6px) rotate(4deg);\n  }\n  76% {\n    transform: scale(var(--scale)) translateX(-6px) rotate(-6deg);\n  }\n  90% {\n    transform: scale(var(--scale)) translateY(4px) scaleY(0.9);\n  }\n  100% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n}\n\n/* のぞきこむ。手前に倒しながら少し大きく ── 画面のこちら側を見にくる */\n@keyframes g-peek {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0) rotate(0deg);\n  }\n  30% {\n    transform: scale(calc(var(--scale) * 1.06)) translateY(6px) rotate(-4deg);\n  }\n  70% {\n    transform: scale(calc(var(--scale) * 1.06)) translateY(6px) rotate(4deg);\n  }\n}\n\n/* 考えこむ。ゆっくり首をひねって、そのまま止まる時間を作る\n   ── 動き続けるより、止まっているほうが「考えている」に見える */\n@keyframes g-ponder {\n  0% {\n    transform: scale(var(--scale)) rotate(0deg) translateY(0);\n  }\n  20%,\n  60% {\n    transform: scale(var(--scale)) rotate(-12deg) translateY(-3px);\n  }\n  80% {\n    transform: scale(var(--scale)) rotate(6deg) translateY(0);\n  }\n  100% {\n    transform: scale(var(--scale)) rotate(0deg) translateY(0);\n  }\n}\n\n/* 手が動いている。小刻みに 4 回、同じ間隔で ── 打鍵のリズム */\n@keyframes g-typing {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0) rotate(0deg);\n  }\n  12% {\n    transform: scale(var(--scale)) translateY(-5px) rotate(-2deg);\n  }\n  25% {\n    transform: scale(var(--scale)) translateY(0) rotate(2deg);\n  }\n  37% {\n    transform: scale(var(--scale)) translateY(-5px) rotate(2deg);\n  }\n  50% {\n    transform: scale(var(--scale)) translateY(0) rotate(-2deg);\n  }\n  62% {\n    transform: scale(var(--scale)) translateY(-5px) rotate(-2deg);\n  }\n  75% {\n    transform: scale(var(--scale)) translateY(0) rotate(2deg);\n  }\n  87% {\n    transform: scale(var(--scale)) translateY(-4px) rotate(0deg);\n  }\n}\n\n/* 寝ながら浮かぶ。ゆっくり大きく、息をしているだけに見える速さで */\n@keyframes g-dream {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0) rotate(0deg);\n  }\n  40% {\n    transform: scale(calc(var(--scale) * 1.03)) translateY(-9px) rotate(-3deg);\n  }\n  70% {\n    transform: scale(var(--scale)) translateY(-4px) rotate(2deg);\n  }\n}\n\n/* くしゃみ。ためて、はじける。速いので目と口も一緒に動かさないと気づけない */\n@keyframes g-sneeze {\n  0% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n  35% {\n    transform: scale(calc(var(--scale) * 0.94)) translateY(4px) scaleY(0.9);\n  }\n  50% {\n    transform: scale(calc(var(--scale) * 1.08)) translateY(-8px) scaleY(1.1);\n  }\n  65% {\n    transform: scale(var(--scale)) translateY(2px);\n  }\n  100% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n}\n\n#stage.g-look #creature {\n  animation: bob 1.7s ease-in-out;\n}\n#stage.g-peek #creature {\n  animation: g-peek 1.6s ease-in-out;\n}\n#stage.g-ponder #creature {\n  animation: g-ponder 2.2s ease-in-out;\n}\n#stage.g-typing #creature {\n  animation: g-typing 1.4s linear;\n}\n#stage.g-dream #creature {\n  animation: g-dream 2.6s ease-in-out;\n}\n#stage.g-sneeze #creature {\n  animation: g-sneeze 0.9s ease-in-out;\n}\n#stage.g-stretch #creature {\n  animation: g-stretch 1.3s ease-in-out;\n}\n#stage.g-tilt #creature {\n  animation: g-tilt 1.2s ease-in-out;\n}\n#stage.g-bounce #creature {\n  animation: g-bounce 1s ease-in-out;\n}\n#stage.g-spin #creature {\n  animation: g-spin 0.9s ease-in-out;\n}\n#stage.g-shiver #creature {\n  animation: g-shiver 0.7s ease-in-out;\n}\n#stage.g-roll #creature {\n  animation: g-roll 2s ease-in-out;\n}\n#stage.g-yawn #creature {\n  animation: g-yawn 1.5s ease-in-out;\n}\n#stage.g-levelup #creature {\n  animation: g-levelup 1.4s ease-in-out;\n}\n#stage.g-battle-win #creature {\n  animation: g-battle-win 3.4s ease-in-out;\n}\n#stage.g-battle-lose #creature {\n  animation: g-battle-lose 3.4s ease-in-out;\n}\n\n/* ---- 待っているあいだの、細かい動き ----------------------------------\n   **何も起きていない時間がいちばん長い。** ここが薄いと、数日で置物に見える。\n   下の 12 個はどれも小道具を持たない身振りなので、絵を足さずに density だけ\n   増やせる ── 大きく動くものと、ほとんど動かないものを混ぜてある\n   （全部が跳ねると、うるさいだけで生き物には見えない）。 */\n\n/* うなずく。**下げるのは速く、戻すのは遅い** ── 逆にすると首振りに見える */\n@keyframes g-nod {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg) translateY(0);\n  }\n  18% {\n    transform: scale(var(--scale)) rotate(9deg) translateY(4px);\n  }\n  40% {\n    transform: scale(var(--scale)) rotate(-2deg) translateY(-1px);\n  }\n  58% {\n    transform: scale(var(--scale)) rotate(7deg) translateY(3px);\n  }\n}\n\n/* 首を振る（ちがう、ちがう）。**縦には動かさない** ── 動かすと、うなずきと混ざる */\n@keyframes g-shake {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg);\n  }\n  20% {\n    transform: scale(var(--scale)) rotate(-8deg);\n  }\n  45% {\n    transform: scale(var(--scale)) rotate(8deg);\n  }\n  70% {\n    transform: scale(var(--scale)) rotate(-5deg);\n  }\n  88% {\n    transform: scale(var(--scale)) rotate(3deg);\n  }\n}\n\n/* 鼻歌。左右に大きくゆっくり ── 動きが小さいので、長めに置くと効く */\n@keyframes g-sway {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateX(0) rotate(0deg);\n  }\n  25% {\n    transform: scale(var(--scale)) translateX(-6px) rotate(-5deg);\n  }\n  50% {\n    transform: scale(var(--scale)) translateX(0) rotate(0deg);\n  }\n  75% {\n    transform: scale(var(--scale)) translateX(6px) rotate(5deg);\n  }\n}\n\n/* 何かに気づいて、ピンと伸びる。**止まる時間を長く取る**のがこの動きの本体 */\n@keyframes g-perk {\n  0% {\n    transform: scale(var(--scale)) translateY(0) scaleY(1);\n  }\n  12% {\n    transform: scale(var(--scale)) translateY(-7px) scaleY(1.1) scaleX(0.95);\n  }\n  22%,\n  72% {\n    transform: scale(var(--scale)) translateY(-4px) scaleY(1.05) scaleX(0.98);\n  }\n  100% {\n    transform: scale(var(--scale)) translateY(0) scaleY(1);\n  }\n}\n\n/* ため息。しぼんで、ゆっくり戻る */\n@keyframes g-sigh {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0) scaleY(1);\n  }\n  25% {\n    transform: scale(var(--scale)) translateY(-3px) scaleY(1.06) scaleX(0.97);\n  }\n  55% {\n    transform: scale(var(--scale)) translateY(5px) scaleY(0.9) scaleX(1.05);\n  }\n  80% {\n    transform: scale(var(--scale)) translateY(2px) scaleY(0.96) scaleX(1.02);\n  }\n}\n\n/* ぐらっとして、持ち直す。**戻りすぎてから収まる**と生き物に見える */\n@keyframes g-wobble {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg) translateX(0);\n  }\n  20% {\n    transform: scale(var(--scale)) rotate(-14deg) translateX(-5px);\n  }\n  45% {\n    transform: scale(var(--scale)) rotate(10deg) translateX(4px);\n  }\n  68% {\n    transform: scale(var(--scale)) rotate(-5deg) translateX(-2px);\n  }\n  85% {\n    transform: scale(var(--scale)) rotate(2deg) translateX(1px);\n  }\n}\n\n/* つまずいて、持ち直す。前に泳いでから戻る */\n@keyframes g-stumble {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translate(0, 0) rotate(0deg);\n  }\n  18% {\n    transform: scale(var(--scale)) translate(-9px, 3px) rotate(-16deg);\n  }\n  34% {\n    transform: scale(var(--scale)) translate(-4px, 6px) rotate(-6deg) scaleY(0.92);\n  }\n  60% {\n    transform: scale(var(--scale)) translate(3px, -2px) rotate(8deg);\n  }\n  82% {\n    transform: scale(var(--scale)) translate(0, 0) rotate(-3deg);\n  }\n}\n\n/* 2 回、小さく跳ねる。bounce より低く速い ── 上機嫌のほう */\n@keyframes g-hop {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateY(0) scaleY(1);\n  }\n  12% {\n    transform: scale(var(--scale)) translateY(0) scaleY(0.88) scaleX(1.08);\n  }\n  30% {\n    transform: scale(var(--scale)) translateY(-11px) scaleY(1.06) scaleX(0.96);\n  }\n  48% {\n    transform: scale(var(--scale)) translateY(0) scaleY(0.9) scaleX(1.06);\n  }\n  66% {\n    transform: scale(var(--scale)) translateY(-8px) scaleY(1.04) scaleX(0.97);\n  }\n  84% {\n    transform: scale(var(--scale)) translateY(0) scaleY(0.95) scaleX(1.03);\n  }\n}\n\n/* 後ろを振り返る。潰して戻すことで「向こうを向いた」に見せる（spin と同じ手） */\n@keyframes g-lookback {\n  0%,\n  100% {\n    transform: scale(var(--scale)) scaleX(1) rotate(0deg);\n  }\n  /* **薄いままの時間を長く取らない。** 潰れた姿で居座ると、振り返ったのではなく\n     絵が壊れているように見える ── 通り抜けるのは一瞬でいい */\n  22% {\n    transform: scale(var(--scale)) scaleX(0.5) rotate(-6deg) translateX(-6px);\n  }\n  38% {\n    transform: scale(var(--scale)) scaleX(0.38) rotate(-2deg) translateX(-8px);\n  }\n  54% {\n    transform: scale(var(--scale)) scaleX(0.62) rotate(4deg) translateX(-5px);\n  }\n  74% {\n    transform: scale(var(--scale)) scaleX(0.9) rotate(3deg) translateX(-2px);\n  }\n}\n\n/* 頭をかく。小刻みに傾けながら、少しだけ浮く */\n@keyframes g-scratch {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg) translateY(0);\n  }\n  20% {\n    transform: scale(var(--scale)) rotate(-11deg) translateY(-2px);\n  }\n  35% {\n    transform: scale(var(--scale)) rotate(-7deg) translateY(-3px);\n  }\n  50% {\n    transform: scale(var(--scale)) rotate(-11deg) translateY(-2px);\n  }\n  65% {\n    transform: scale(var(--scale)) rotate(-7deg) translateY(-3px);\n  }\n  85% {\n    transform: scale(var(--scale)) rotate(-3deg) translateY(-1px);\n  }\n}\n\n/* 集中する。**ほとんど動かない** ── 少しだけ前に出て、そのまま止まる。\n   賑やかな動きばかりだと、止まっている瞬間が効かなくなる */\n@keyframes g-focus {\n  0% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n  18%,\n  82% {\n    transform: scale(calc(var(--scale) * 1.03)) translateY(3px);\n  }\n  100% {\n    transform: scale(var(--scale)) translateY(0);\n  }\n}\n\n/* 寝息。ゆっくり膨らんで、しぼむ */\n@keyframes g-snore {\n  0%,\n  100% {\n    transform: scale(var(--scale)) scaleY(1) scaleX(1) translateY(0);\n  }\n  40% {\n    transform: scale(var(--scale)) scaleY(1.05) scaleX(1.04) translateY(-3px);\n  }\n  70% {\n    transform: scale(var(--scale)) scaleY(0.97) scaleX(1.01) translateY(1px);\n  }\n}\n\n/* 寝返り。roll が横に転がるのに対して、こちらは**向きを変えて落ち着く** */\n@keyframes g-turnover {\n  0% {\n    transform: scale(var(--scale)) rotate(0deg) translateX(0);\n  }\n  30% {\n    transform: scale(var(--scale)) rotate(-18deg) translateX(-7px) scaleY(0.94);\n  }\n  55% {\n    transform: scale(var(--scale)) rotate(4deg) translateX(5px) scaleX(0.9);\n  }\n  80% {\n    transform: scale(var(--scale)) rotate(12deg) translateX(6px);\n  }\n  100% {\n    transform: scale(var(--scale)) rotate(8deg) translateX(4px);\n  }\n}\n\n#stage.g-nod #creature {\n  animation: g-nod 1.3s ease-in-out;\n}\n#stage.g-shake #creature {\n  animation: g-shake 1.2s ease-in-out;\n}\n#stage.g-sway #creature {\n  animation: g-sway 2.4s ease-in-out;\n}\n#stage.g-perk #creature {\n  animation: g-perk 1.8s ease-out;\n}\n#stage.g-sigh #creature {\n  animation: g-sigh 1.9s ease-in-out;\n}\n#stage.g-wobble #creature {\n  animation: g-wobble 1.4s ease-in-out;\n}\n#stage.g-stumble #creature {\n  animation: g-stumble 1.5s ease-in-out;\n}\n#stage.g-hop #creature {\n  animation: g-hop 1.2s ease-in-out;\n}\n#stage.g-lookback #creature {\n  animation: g-lookback 1.6s ease-in-out;\n}\n#stage.g-scratch #creature {\n  animation: g-scratch 1.5s ease-in-out;\n}\n#stage.g-focus #creature {\n  animation: g-focus 2s ease-in-out;\n}\n#stage.g-snore #creature {\n  animation: g-snore 2.8s ease-in-out;\n}\n#stage.g-turnover #creature {\n  animation: g-turnover 2.4s ease-in-out;\n}\n\n/* ── 型（persona.js）で顔つきが変わる ──────────────────────\n   4 文字ぶんのクラス（p-E / p-I / …）が #stage に付く。\n   **型が字面だけにならないように**、目つきと口元をその人の使い方で変える。\n   気分やしぐさのアニメーションとは別のプロパティしか触らないので、\n   どのしぐさの最中でも顔だけは型のまま残る。 */\n\n/* 刻む人は瞳が小さい（一点を見ている）／委ねる人は大きい（放っている） */\n#stage.p-cut .pupil {\n  r: 3;\n}\n#stage.p-trust .pupil {\n  r: 6.3;\n}\n\n/* 外に出て行く人は口が大きい／籠る人は結んでいる */\n#stage.p-out #mouth {\n  d: path('M89 143 Q 100 159 111 143');\n}\n#stage.p-in #mouth {\n  d: path('M95 147 Q 100 149 105 147');\n}\n\n/* 組み立てる人は目が寄っている（近くを見る）／動かす人は離れて広く見る */\n#stage.p-build #face {\n  transform: scaleX(0.88);\n  transform-origin: 100px 130px;\n}\n#stage.p-move #face {\n  transform: scaleX(1.12);\n  transform-origin: 100px 130px;\n}\n\n/* 走り切る人はまぶたが少し下りている（腰を据えている）／散らす人は見開いている */\n#stage.p-through .eyeball {\n  r: 8.6;\n}\n#stage.p-spread .eyeball {\n  r: 12.1;\n}\n\n/* きょろきょろ。体は普通に揺れているので、動かすのは目だけ */\n@keyframes g-eyes {\n  0%,\n  100% {\n    transform: translate(0, 0);\n  }\n  25% {\n    transform: translate(-3.5px, 0);\n  }\n  60% {\n    transform: translate(3.5px, -1px);\n  }\n}\n#stage.g-look .pupil {\n  animation: g-eyes 1.7s ease-in-out;\n}\n\n/* あくび。口が開いて、目が閉じる。\n   線だけだと小さくて気づけないので、開いている間は中を塗る。 */\n@keyframes g-mouth {\n  0%,\n  100% {\n    d: path('M94 145 Q 100 149 106 145');\n    fill: transparent;\n  }\n  45% {\n    d: path('M90 140 Q 100 166 110 140');\n    fill: var(--ink);\n  }\n}\n#stage.g-yawn #mouth {\n  animation: g-mouth 1.5s ease-in-out;\n}\n#stage.g-yawn .lid {\n  opacity: 1;\n}\n#stage.g-yawn .pupil,\n#stage.g-yawn .eyeball {\n  opacity: 0;\n}\n\n/* のぞきこむときは瞳を下げる。体だけ倒しても、目が前を向いていないと\n   「近づいてきた」ではなく「傾いた」に見える */\n@keyframes g-eyes-down {\n  0%,\n  100% {\n    transform: translate(0, 0);\n  }\n  30%,\n  70% {\n    transform: translate(0, 2.5px);\n  }\n}\n#stage.g-peek .pupil {\n  animation: g-eyes-down 1.6s ease-in-out;\n}\n\n/* 考えこむときは上を見る。首をひねっている間だけ、瞳が斜め上で止まる */\n@keyframes g-eyes-up {\n  0%,\n  100% {\n    transform: translate(0, 0);\n  }\n  20%,\n  60% {\n    transform: translate(-2px, -3px);\n  }\n}\n#stage.g-ponder .pupil {\n  animation: g-eyes-up 2.2s ease-in-out;\n}\n\n/* 寝言のあいだは目を閉じたまま */\n#stage.g-dream .lid {\n  opacity: 1;\n}\n#stage.g-dream .pupil,\n#stage.g-dream .eyeball {\n  opacity: 0;\n}\n\n/* くしゃみ。はじける一瞬だけ目をつぶって、口が開く */\n@keyframes g-sneeze-eyes {\n  0%,\n  100% {\n    opacity: 1;\n  }\n  40%,\n  60% {\n    opacity: 0;\n  }\n}\n@keyframes g-sneeze-mouth {\n  0%,\n  100% {\n    d: path('M94 145 Q 100 149 106 145');\n    fill: transparent;\n  }\n  50% {\n    d: path('M94 142 Q 100 159 106 142');\n    fill: var(--ink);\n  }\n}\n#stage.g-sneeze .pupil,\n#stage.g-sneeze .eyeball {\n  animation: g-sneeze-eyes 0.9s ease-in-out;\n}\n#stage.g-sneeze #mouth {\n  animation: g-sneeze-mouth 0.9s ease-in-out;\n}\n\n/* 戦っている間だけ、足元の影を踏み込みに合わせて動かす */\n@keyframes g-shadow {\n  0%,\n  100% {\n    transform: translateX(0) scaleX(1);\n  }\n  26%,\n  48% {\n    transform: translateX(14px) scaleX(0.86);\n  }\n}\n#stage.g-battle-win #shadow,\n#stage.g-battle-lose #shadow {\n  animation: g-shadow 3.4s ease-in-out;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  #creature,\n  #aura ellipse,\n  #shadow,\n  #mouth,\n  .pupil {\n    animation: none !important;\n  }\n}\n\n\n/* ---- 暮らし ----------------------------------------------------------\n   画面の前にいる間、ずっと何かしている（shared/gestures.js の ACTIVITIES）。\n   しぐさが 1〜2 秒の身振りなのに対して、こちらは 4〜7 秒の場面で、\n   たいてい小道具を持つ。\n\n   小道具は **既定で消えていて**、その場面のクラスが付いたときだけ出る。\n   #creature の外に置いてあるので、体の伸び縮みに巻き込まれない\n   ── 巻き込むと、伸びをするたびに丼まで伸びる。 */\n\n.prop {\n  opacity: 0;\n  transition: opacity 0.25s ease;\n}\n.prop * {\n  transform-box: fill-box;\n  transform-origin: center;\n}\n\n/* 小道具の色。体と同じ色相に乗せて、画面の中で浮かないようにする */\n#props .bun,\n#props .basket,\n#props .bowl,\n#props .cup,\n#props .paper,\n#props .page,\n#props .screen {\n  fill: hsl(var(--hue) 24% 82%);\n  stroke: var(--ink);\n  stroke-width: 2.5;\n  stroke-linejoin: round;\n}\n#props .patty,\n#props .head,\n#props .spine,\n#props .fold,\n#props .stand,\n#props .handle,\n#props .chopsticks,\n#props .tip {\n  fill: var(--ink);\n  stroke: none;\n}\n#props .spine,\n#props .fold {\n  fill: none;\n  stroke: var(--ink);\n  stroke-width: 2.5;\n}\n#props .leaf,\n#props .dumpling,\n#props .lens,\n#props .cloth {\n  fill: var(--body);\n  stroke: var(--body-dark);\n  stroke-width: 2.5;\n}\n#props .tube {\n  fill: var(--body-dark);\n}\n#props .noodle,\n#props .steam path {\n  fill: none;\n  stroke: var(--ink);\n  stroke-width: 2.5;\n  stroke-linecap: round;\n  opacity: 0.75;\n}\n#props .flicker {\n  fill: hsl(var(--hue) 60% 70%);\n}\n\n/* 場面ごとに、その回に要る小道具だけ出す */\n#stage.g-burger #prop-burger,\n#stage.g-bun #prop-bun,\n#stage.g-soba #prop-soba,\n#stage.g-tea #prop-tea,\n#stage.g-movie #prop-movie,\n#stage.g-nap #prop-blanket,\n#stage.g-doze #prop-blanket,\n#stage.g-reading #prop-book,\n#stage.g-hammering #prop-hammer,\n#stage.g-carving #prop-brush,\n#stage.g-scouting #prop-scope,\n#stage.g-sending #prop-letter,\n#stage.g-cat #prop-cat,\n#stage.g-catnap #prop-cat,\n#stage.g-bird #prop-bird,\n#stage.g-turtle #prop-turtle {\n  opacity: 1;\n}\n\n/* 食べる ── 口へ運んで、噛んで、また運ぶ。体は少し傾く */\n@keyframes g-eat {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg);\n  }\n  15%,\n  45%,\n  75% {\n    transform: scale(var(--scale)) rotate(7deg) translateX(4px);\n  }\n  30%,\n  60%,\n  90% {\n    transform: scale(var(--scale)) rotate(4deg) translateX(2px) scaleY(0.97);\n  }\n}\n\n/* 食べ物は**口まで**寄っていって、少しずつ減る。\n   寄せ幅が足りないと、頬のあたりで齧っている絵になる（-16px だとそうだった）。 */\n@keyframes prop-eaten {\n  0% {\n    transform: translate(0, 0) scale(1);\n  }\n  25% {\n    transform: translate(-34px, 4px) scale(0.94);\n  }\n  55% {\n    transform: translate(-34px, 4px) scale(0.72);\n  }\n  80% {\n    transform: translate(-34px, 4px) scale(0.5);\n  }\n  100% {\n    transform: translate(-34px, 4px) scale(0.35);\n    opacity: 0;\n  }\n}\n\n/*\n * 食べる 3 つ。**長さは gestures.js の ms と合わせる** ── 3 つまとめて 5.2s に\n * していたので、そば（5.6s）とあんまん（5.4s）は食べ終わってから\n * 0.2〜0.4 秒ぶん止まったまま待っていた。ついでに 3 つとも違う長さになって、\n * 続けて出たときに同じ動きの繰り返しに見えにくくなる。\n */\n#stage.g-burger #creature {\n  animation: g-eat 5.2s ease-in-out;\n}\n#stage.g-bun #creature {\n  animation: g-eat 5.4s ease-in-out;\n}\n#stage.g-soba #creature {\n  animation: g-eat 5.6s ease-in-out;\n}\n#stage.g-burger #prop-burger,\n#stage.g-bun #prop-bun,\n#stage.g-soba #prop-soba {\n  animation: prop-eaten 5.2s ease-in-out;\n}\n\n/* 湯気は、湯気らしくゆっくり上がる */\n@keyframes prop-steam {\n  0% {\n    opacity: 0;\n    transform: translateY(4px);\n  }\n  40% {\n    opacity: 0.8;\n  }\n  100% {\n    opacity: 0;\n    transform: translateY(-10px);\n  }\n}\n#stage.g-bun .steam path,\n#stage.g-tea .steam path {\n  animation: prop-steam 2.4s ease-out infinite;\n}\n#stage.g-bun .steam path:nth-child(2),\n#stage.g-tea .steam path:nth-child(2) {\n  animation-delay: 0.8s;\n}\n\n/* お茶 ── すすって、ひと息 */\n@keyframes g-sip {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg);\n  }\n  25%,\n  55% {\n    transform: scale(var(--scale)) rotate(6deg) translateY(2px);\n  }\n  70% {\n    transform: scale(var(--scale)) rotate(0deg) scaleY(1.03);\n  }\n}\n#stage.g-tea #creature {\n  animation: g-sip 4.4s ease-in-out;\n}\n\n/* 映画 ── 画面のほうを向いて、たまに笑う。光は不規則に瞬く */\n@keyframes g-watch {\n  0%,\n  100% {\n    transform: scale(var(--scale)) translateX(0);\n  }\n  20% {\n    transform: scale(var(--scale)) translateX(-6px) rotate(-3deg);\n  }\n  55% {\n    transform: scale(var(--scale)) translateX(-6px) rotate(-3deg) translateY(-4px);\n  }\n  80% {\n    transform: scale(var(--scale)) translateX(-4px) rotate(-2deg);\n  }\n}\n@keyframes prop-flicker {\n  0%,\n  100% {\n    opacity: 0.35;\n  }\n  20% {\n    opacity: 0.9;\n  }\n  35% {\n    opacity: 0.5;\n  }\n  60% {\n    opacity: 1;\n  }\n  75% {\n    opacity: 0.45;\n  }\n}\n#stage.g-movie #creature {\n  animation: g-watch 7s ease-in-out;\n}\n#stage.g-movie .flicker {\n  animation: prop-flicker 1.1s steps(1, end) infinite;\n}\n/* 観ているあいだは瞳も画面のほうへ寄る */\n#stage.g-movie .pupil {\n  transform: translate(-3px, 0);\n}\n\n/* 昼寝 ── 布団がかかって、ゆっくり息をする */\n@keyframes g-nap {\n  0%,\n  100% {\n    transform: scale(var(--scale)) scaleY(0.94) translateY(6px);\n  }\n  50% {\n    transform: scale(var(--scale)) scaleY(0.99) translateY(4px);\n  }\n}\n@keyframes prop-tuck {\n  0% {\n    transform: translateY(18px);\n    opacity: 0;\n  }\n  15%,\n  85% {\n    transform: translateY(0);\n    opacity: 1;\n  }\n  100% {\n    transform: translateY(18px);\n    opacity: 0;\n  }\n}\n#stage.g-nap #creature,\n#stage.g-doze #creature {\n  animation: g-nap 3.2s ease-in-out infinite;\n}\n#stage.g-nap #prop-blanket,\n#stage.g-doze #prop-blanket {\n  animation: prop-tuck 6s ease-in-out;\n}\n#stage.g-nap .lid,\n#stage.g-doze .lid {\n  opacity: 1;\n}\n#stage.g-nap .pupil,\n#stage.g-nap .eyeball,\n#stage.g-doze .pupil,\n#stage.g-doze .eyeball {\n  opacity: 0;\n}\n\n/* 読む ── あなたが出てきたものを追っている間、相棒も本を読む。\n   ページを追って、視線が左右に流れる */\n@keyframes g-reading {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg) translateY(0);\n  }\n  50% {\n    transform: scale(var(--scale)) rotate(2deg) translateY(3px);\n  }\n}\n@keyframes prop-page {\n  0%,\n  100% {\n    transform: translateY(0) rotate(0deg);\n  }\n  48% {\n    transform: translateY(-2px) rotate(-2deg);\n  }\n}\n@keyframes g-read-eyes {\n  0%,\n  100% {\n    transform: translate(-3px, 3px);\n  }\n  50% {\n    transform: translate(3px, 3px);\n  }\n}\n#stage.g-reading #creature {\n  animation: g-reading 5s ease-in-out infinite;\n}\n#stage.g-reading #prop-book {\n  animation: prop-page 1.6s ease-in-out infinite;\n}\n#stage.g-reading .pupil {\n  animation: g-read-eyes 1.6s ease-in-out infinite;\n}\n\n/* 叩く ── Bash が走っている間。金づちが上下する */\n@keyframes g-hammering {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg);\n  }\n  25% {\n    transform: scale(var(--scale)) rotate(5deg) translateY(-2px);\n  }\n  40% {\n    transform: scale(var(--scale)) rotate(2deg) translateY(2px) scaleY(0.96);\n  }\n}\n@keyframes prop-swing {\n  0%,\n  100% {\n    transform: rotate(-8deg);\n  }\n  45% {\n    transform: rotate(42deg) translateY(6px);\n  }\n}\n#stage.g-hammering #creature {\n  animation: g-hammering 0.7s ease-in-out infinite;\n}\n#stage.g-hammering #prop-hammer {\n  animation: prop-swing 0.7s ease-in-out infinite;\n  transform-origin: 154px 144px;\n}\n\n/* 彫る（書く）── 筆で細かく手を動かす */\n@keyframes prop-stroke {\n  0%,\n  100% {\n    transform: translate(0, 0) rotate(0deg);\n  }\n  30% {\n    transform: translate(-3px, 3px) rotate(-6deg);\n  }\n  60% {\n    transform: translate(2px, 1px) rotate(4deg);\n  }\n}\n#stage.g-carving #creature {\n  animation: g-typing 1.4s linear infinite;\n}\n#stage.g-carving #prop-brush {\n  animation: prop-stroke 0.9s ease-in-out infinite;\n}\n\n/* 望遠鏡 ── 外を見に行っているあいだ、遠くを覗く */\n@keyframes g-scouting {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(-4deg);\n  }\n  40% {\n    transform: scale(var(--scale)) rotate(-9deg) translateY(-3px);\n  }\n  70% {\n    transform: scale(var(--scale)) rotate(-2deg);\n  }\n}\n#stage.g-scouting #creature {\n  animation: g-scouting 4.8s ease-in-out;\n}\n#stage.g-scouting .pupil {\n  transform: translate(3px, -3px);\n}\n\n/* 手紙 ── 任せたぶんが飛んでいく */\n@keyframes prop-fly {\n  0% {\n    transform: translate(0, 0) rotate(0deg);\n    opacity: 0;\n  }\n  20% {\n    opacity: 1;\n  }\n  100% {\n    transform: translate(26px, -46px) rotate(18deg);\n    opacity: 0;\n  }\n}\n#stage.g-sending #creature {\n  animation: g-bounce 1s ease-in-out;\n}\n#stage.g-sending #prop-letter {\n  animation: prop-fly 2.2s ease-in infinite;\n}\n\n/* ------------------------------------------------------------------ *\n * スキン ── 見た目の重ね着（src/core/skins.js）\n *\n * **数字に一切触らない。** ここで変えるのは色と、体に重ねる 1 枚と、\n * 小物 1 つだけ。目つきと口元（型 = persona.js が決めるもの）には\n * 一切掛からない ── **顔つきはスキンで買えない**。\n *\n * 色は #stage の変数を差し替えるだけなので、系統色（--hue）を上書きしない\n * スキンでは、働き方の色がそのまま透ける。\n * ------------------------------------------------------------------ */\n\n/* 模様と小物は、既定では全部消えている（props と同じ作り） */\n.tex,\n.trinket {\n  opacity: 0;\n}\n\n#skin-texture {\n  pointer-events: none;\n}\n\n/* ---- 墨 ---- */\n#stage.skin-mono {\n  --sat: 6%;\n  --body: hsl(var(--hue) var(--sat) 58%);\n  --body-dark: hsl(var(--hue) var(--sat) 34%);\n}\n#stage.skin-mono #tex-grain {\n  opacity: 0.14;\n}\n#tex-grain path {\n  fill: none;\n  stroke: var(--ink);\n  stroke-width: 1;\n}\n\n/* ---- 熾火 ---- */\n#stage.skin-ember {\n  --hue: 16;\n  --sat: 72%;\n  --body: hsl(var(--hue) var(--sat) 58%);\n  --body-dark: hsl(var(--hue) var(--sat) 34%);\n  --ink: hsl(14 60% 16%);\n}\n#stage.skin-ember #tex-ember {\n  opacity: 0.5;\n}\n#stage.skin-ember #trinket-spark {\n  opacity: 1;\n}\n#tex-ember ellipse {\n  fill: hsl(42 100% 62%);\n}\n#trinket-spark circle {\n  fill: hsl(42 100% 68%);\n  animation: spark 2.4s ease-in-out infinite;\n}\n#trinket-spark circle:nth-child(2) {\n  animation-delay: 0.5s;\n}\n#trinket-spark circle:nth-child(3) {\n  animation-delay: 1.1s;\n}\n\n/* 火の粉は上に抜けて消える。**跳ねさせない** ── 常駐の画面で暴れると疲れる */\n@keyframes spark {\n  0% {\n    opacity: 0;\n    transform: translateY(4px);\n  }\n  30% {\n    opacity: 0.9;\n  }\n  100% {\n    opacity: 0;\n    transform: translateY(-12px);\n  }\n}\n\n/* ---- 霜 ---- */\n#stage.skin-frost {\n  --hue: 196;\n  --sat: 55%;\n  --body: hsl(var(--hue) var(--sat) 72%);\n  --body-dark: hsl(var(--hue) var(--sat) 48%);\n  --ink: hsl(205 45% 24%);\n}\n#stage.skin-frost #tex-frost {\n  opacity: 0.55;\n}\n#stage.skin-frost #trinket-breath {\n  opacity: 1;\n}\n#tex-frost path {\n  fill: none;\n  stroke: #fff;\n  stroke-width: 2;\n  stroke-linecap: round;\n}\n#trinket-breath ellipse {\n  fill: #fff;\n  animation: breath 4.6s ease-in-out infinite;\n}\n#trinket-breath ellipse:nth-child(2) {\n  animation-delay: 0.35s;\n}\n#trinket-breath ellipse:nth-child(3) {\n  animation-delay: 0.7s;\n}\n\n@keyframes breath {\n  0%,\n  60% {\n    opacity: 0;\n  }\n  70% {\n    opacity: 0.75;\n  }\n  100% {\n    opacity: 0;\n    transform: translate(8px, -4px);\n  }\n}\n\n/* ---- 宵 ---- */\n#stage.skin-dusk {\n  --hue: 268;\n  --sat: 48%;\n  --body: hsl(var(--hue) var(--sat) 52%);\n  --body-dark: hsl(var(--hue) var(--sat) 30%);\n  --ink: hsl(265 40% 88%);\n}\n#stage.skin-dusk #tex-stars {\n  opacity: 0.85;\n}\n#stage.skin-dusk #trinket-moth {\n  opacity: 1;\n}\n#tex-stars circle {\n  fill: #fff;\n  animation: twinkle 5.2s ease-in-out infinite;\n}\n#tex-stars circle:nth-child(2n) {\n  animation-delay: 1.3s;\n}\n#tex-stars circle:nth-child(3n) {\n  animation-delay: 2.6s;\n}\n#trinket-moth path {\n  fill: hsl(48 40% 84%);\n}\n#trinket-moth circle {\n  fill: var(--body-dark);\n}\n#trinket-moth {\n  transform-origin: 55px 90px;\n  animation: flutter 3.8s ease-in-out infinite;\n}\n\n@keyframes twinkle {\n  0%,\n  100% {\n    opacity: 0.35;\n  }\n  50% {\n    opacity: 1;\n  }\n}\n\n@keyframes flutter {\n  0%,\n  100% {\n    transform: translate(0, 0);\n  }\n  35% {\n    transform: translate(-4px, -6px);\n  }\n  70% {\n    transform: translate(3px, -2px);\n  }\n}\n\n\n/* ------------------------------------------------------------------ *\n * じゃれてくる相手（gestures.js の cat / bird / turtle）\n *\n * **世話をするものではない。** 餌やりも撫でるボタンも無く、向こうから来て\n * 勝手に帰る ── こちらができるのは眺めることだけ（DESIGN.md §3）。\n *\n * 動きは 2 つに分かれる。相手は歩いてきて遊んで帰る（prop 側）、\n * こちらは相手のほうに体を傾ける（creature 側）── 両方が動かないと、\n * 「同じ画面に 2 匹いる」だけで「じゃれている」に見えない。\n * ------------------------------------------------------------------ */\n\n#props .fur {\n  fill: hsl(28 34% 74%);\n  stroke: var(--ink);\n  stroke-width: 2.5;\n  stroke-linejoin: round;\n}\n#props .beady {\n  fill: var(--ink);\n  stroke: none;\n}\n#props .tail,\n#props .whisker,\n#props .wing,\n#props .foot,\n#props .shellline {\n  fill: none;\n  stroke: var(--ink);\n  stroke-width: 2.5;\n  stroke-linecap: round;\n}\n#props .whisker {\n  opacity: 0.5;\n  stroke-width: 2;\n}\n#props .beak {\n  fill: hsl(38 80% 60%);\n  stroke: none;\n}\n#prop-turtle .fur {\n  fill: hsl(120 26% 62%);\n}\n#prop-bird .fur {\n  fill: hsl(200 40% 76%);\n}\n\n/*\n * 猫は横から来て、しっぽを振りながら居座る。\n *\n * **動きは必ず場面のクラスの下に置く。** 素の `#prop-cat` に付けると、\n * opacity を持つキーフレームが常に走って、`.prop { opacity: 0 }` を上書きする\n * ── 消えているはずの猫と小鳥と亀が、いつも全部出ていた。\n */\n#stage.g-cat #prop-cat {\n  animation: cat-visit 6.4s ease-out;\n}\n#stage.g-cat #prop-cat .tail {\n  transform-box: fill-box;\n  transform-origin: left center;\n  animation: tail-flick 1.1s ease-in-out infinite;\n}\n\n/*\n * 猫は歩いて来る。**一定速度で滑らせない** ── 滑ると、生き物ではなく\n * 板が動いているように見えた。歩幅ぶんの上下（1〜2px）を刻みながら寄ってきて、\n * 一度とびかかって、座って、また歩いて帰る。\n */\n@keyframes cat-visit {\n  0% {\n    transform: translate(54px, 0);\n    opacity: 0;\n  }\n  5% {\n    transform: translate(48px, -1px);\n    opacity: 1;\n  }\n  10% {\n    transform: translate(40px, 1px);\n  }\n  15% {\n    transform: translate(32px, -1px);\n  }\n  20% {\n    transform: translate(24px, 1px);\n  }\n  25% {\n    transform: translate(16px, -1px);\n  }\n  30% {\n    transform: translate(10px, 1px);\n  }\n  /* 一度沈んでから、とびかかる */\n  36% {\n    transform: translate(6px, 3px) scale(0.96);\n  }\n  /* とびかかるのは**上へ**。左へ寄せると相棒の体に重なって、頭だけ出た\n     よく分からない生き物になる（枠の外に置いてある意味が消える） */\n  42% {\n    transform: translate(3px, -11px) scale(1.06);\n  }\n  48% {\n    transform: translate(0, 0) scale(1);\n  }\n  52%,\n  72% {\n    transform: translate(0, 0);\n    opacity: 1;\n  }\n  /* 帰りは背を向けるので、少しだけ縮めて向きの変化に見せる */\n  78% {\n    transform: translate(12px, -1px) scaleX(0.94);\n  }\n  84% {\n    transform: translate(26px, 1px) scaleX(0.94);\n  }\n  92% {\n    transform: translate(42px, -1px) scaleX(0.94);\n    opacity: 1;\n  }\n  100% {\n    transform: translate(56px, 0) scaleX(0.94);\n    opacity: 0;\n  }\n}\n\n@keyframes tail-flick {\n  0%,\n  100% {\n    transform: rotate(0deg);\n  }\n  50% {\n    transform: rotate(-22deg);\n  }\n}\n\n/* 小鳥は上から降りてきて、頭のあたりで跳ねる */\n#stage.g-bird #prop-bird {\n  animation: bird-visit 5.6s ease-in-out;\n}\n#stage.g-bird #prop-bird .wing {\n  transform-box: fill-box;\n  transform-origin: right center;\n  animation: wing-flap 0.5s ease-in-out infinite;\n}\n\n/*\n * **降りるのは弧を描かせる。** 真っ直ぐ降ろすと落ちてきたように見える。\n * 着いたら 2 回ついばんで、跳ねて、翼を広げて上へ抜ける。\n */\n@keyframes bird-visit {\n  0% {\n    transform: translate(34px, -46px) rotate(14deg);\n    opacity: 0;\n  }\n  8% {\n    transform: translate(26px, -30px) rotate(10deg);\n    opacity: 1;\n  }\n  16% {\n    transform: translate(12px, -14px) rotate(4deg);\n  }\n  22% {\n    transform: translate(2px, -2px) rotate(0deg);\n  }\n  26% {\n    transform: translate(0, 0);\n  }\n  /* ついばむ ── 前に倒して、戻す */\n  34% {\n    transform: translate(1px, 3px) rotate(16deg);\n  }\n  40% {\n    transform: translate(0, 0) rotate(0deg);\n  }\n  46% {\n    transform: translate(1px, 3px) rotate(16deg);\n  }\n  52% {\n    transform: translate(0, 0) rotate(0deg);\n  }\n  /* 跳ねる */\n  60% {\n    transform: translate(-2px, -7px);\n  }\n  66% {\n    transform: translate(-4px, 0);\n  }\n  74% {\n    transform: translate(-4px, 0);\n    opacity: 1;\n  }\n  86% {\n    transform: translate(6px, -22px) rotate(-8deg);\n    opacity: 1;\n  }\n  100% {\n    transform: translate(22px, -52px) rotate(-16deg);\n    opacity: 0;\n  }\n}\n\n@keyframes wing-flap {\n  0%,\n  100% {\n    transform: rotate(0deg);\n  }\n  50% {\n    transform: rotate(-30deg);\n  }\n}\n\n/* 亀は急がない。**出るのも帰るのも遅い**のが、この相手の芸 */\n#stage.g-turtle #prop-turtle {\n  animation: turtle-visit 6.8s linear;\n}\n/* 甲羅を左右にゆっくり傾ける ── 足が見えなくても、歩いているように見える */\n#stage.g-turtle #prop-turtle .fur {\n  transform-box: fill-box;\n  transform-origin: center bottom;\n  animation: turtle-rock 1.6s ease-in-out infinite;\n}\n\n@keyframes turtle-visit {\n  0% {\n    transform: translateX(42px);\n    opacity: 0;\n  }\n  12% {\n    opacity: 1;\n  }\n  /* 一度止まって、顔を上げる（首を伸ばすぶんだけ縦に伸ばす） */\n  40% {\n    transform: translateX(6px) scaleY(1);\n  }\n  48% {\n    transform: translateX(4px) scaleY(1.08);\n  }\n  58% {\n    transform: translateX(2px) scaleY(1);\n  }\n  72% {\n    transform: translateX(-4px);\n    opacity: 1;\n  }\n  100% {\n    transform: translateX(-18px);\n    opacity: 0;\n  }\n}\n\n@keyframes turtle-rock {\n  0%,\n  100% {\n    transform: rotate(-3deg);\n  }\n  50% {\n    transform: rotate(3deg);\n  }\n}\n\n/* ---- こちら側の動き ----\n   **必ず scale(var(--scale)) から書く。** 抜くと、しぐさに入った瞬間に\n   レベルぶんの大きさが飛ぶ。 */\n\n/* 猫にじゃれる ── 覗きこんで、ちょっかいを出して、また戻る */\n@keyframes g-cat {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg) translateX(0);\n  }\n  20% {\n    transform: scale(var(--scale)) rotate(9deg) translateX(6px);\n  }\n  35% {\n    transform: scale(var(--scale)) rotate(4deg) translateX(3px) translateY(-4px);\n  }\n  50% {\n    transform: scale(var(--scale)) rotate(11deg) translateX(7px);\n  }\n  70% {\n    transform: scale(var(--scale)) rotate(2deg) translateX(2px) translateY(-3px);\n  }\n}\n\n/* 頭にとまられた ── 落とさないように、そっとしている */\n@keyframes g-bird {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg);\n  }\n  20%,\n  80% {\n    transform: scale(var(--scale)) rotate(-2deg) translateY(1px);\n  }\n  50% {\n    transform: scale(var(--scale)) rotate(2deg) translateY(1px);\n  }\n}\n\n/* 亀を見送る ── ゆっくり首をかしげるだけ */\n@keyframes g-turtle {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg);\n  }\n  40% {\n    transform: scale(var(--scale)) rotate(7deg) translateY(2px);\n  }\n  75% {\n    transform: scale(var(--scale)) rotate(3deg);\n  }\n}\n\n/* 猫と一緒に寝る ── 二匹とも動かない。息だけしている */\n@keyframes g-catnap {\n  0%,\n  100% {\n    transform: scale(var(--scale)) rotate(0deg) scaleY(0.99);\n  }\n  50% {\n    transform: scale(var(--scale)) rotate(1deg) scaleY(1.02);\n  }\n}\n\n#stage.g-cat #creature {\n  animation: g-cat 6.4s ease-in-out;\n}\n#stage.g-bird #creature {\n  animation: g-bird 5.6s ease-in-out;\n}\n#stage.g-turtle #creature {\n  animation: g-turtle 6.8s ease-in-out;\n}\n#stage.g-catnap #creature {\n  animation: g-catnap 3.5s ease-in-out infinite;\n}\n\n/* 寝ているところに来た猫は、丸まって動かない（歩いて帰らない） */\n#stage.g-catnap #prop-cat {\n  animation: cat-curl 7s ease-in-out;\n}\n#stage.g-catnap #prop-cat .tail {\n  animation: none;\n}\n\n@keyframes cat-curl {\n  0% {\n    transform: translateX(40px);\n    opacity: 0;\n  }\n  20%,\n  100% {\n    transform: translate(-4px, 6px) scale(0.92);\n    opacity: 1;\n  }\n}\n\n/* ---- 空 -------------------------------------------------------------\n   **いちばん長く見ている画面が「何も起きていないオーバーレイ」**なので\n   （DESIGN.md §5c）、そこが 1 日じゅう同じ色なのはもったいない。\n\n   **見た目だけ。数字には一切効かない** ── 効かせると「夜に働くと得」が\n   生まれて、§1（戦闘力の出どころは作業ログ）に別の入口ができる。\n\n   **窓の内側で必ず消えきる大きさにする。** オーバーレイの背景は完全透明で\n   なければならず（このファイルの先頭）、窓の縁に届く光を置くと、そこで\n   ばっさり切れて**デスクトップに四角が出る**。だから中心は下寄り、半径は\n   40% / 26% ── 200x200 の中で x 20〜180・y 92〜196 に収まる。 */\n\n#stage {\n  transition: background 8s ease;\n}\n\n#stage.sky-dawn {\n  background: radial-gradient(40% 26% at 50% 72%, hsl(22 62% 42% / 0.55), transparent 100%);\n}\n#stage.sky-day {\n  background: radial-gradient(40% 26% at 50% 72%, hsl(200 52% 46% / 0.4), transparent 100%);\n}\n#stage.sky-dusk {\n  background: radial-gradient(40% 26% at 50% 72%, hsl(288 50% 42% / 0.5), transparent 100%);\n}\n#stage.sky-night {\n  background: radial-gradient(40% 26% at 50% 72%, hsl(226 58% 34% / 0.6), transparent 100%);\n}\n\n/* 夜だけ、影を少し薄くして沈ませる */\n#stage.sky-night #shadow {\n  opacity: 0.3;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  #stage {\n    transition: none;\n  }\n}\n" },
  "mobile.css": { type: "text/css; charset=utf-8", body: "/* pet.css（オーバーレイ用）を先に読んでいるので、ここでページ用に上書きする。 */\n\n/*\n * pet.css は色のトークンを #stage の中だけに置いている（オーバーレイには\n * キャラしか無いので足りる）。このページはキャラの外にも系統色を使うので、\n * ページ全体に届くよう :root にも同じトークンを持たせる。\n */\n:root {\n  --hue: 220;\n  --sat: 12%;\n  --body: hsl(var(--hue) var(--sat) 62%);\n}\n\nhtml,\nbody {\n  background: #12141a;\n  color: #e8ecf4;\n  overflow: auto;\n  cursor: default;\n}\n\nmain {\n  max-width: 520px;\n  margin: 0 auto;\n  padding: 24px 20px calc(32px + env(safe-area-inset-bottom));\n}\n\n/* オーバーレイでは絶対配置の 200x200 だが、ここでは中央に置く箱として使う */\n#stage {\n  margin: 0 auto;\n  --hue: 220;\n  --sat: 12%;\n}\n\nh1 {\n  margin: 4px 0 2px;\n  font-size: 34px;\n  font-weight: 800;\n  text-align: center;\n  letter-spacing: 0.02em;\n}\n\n#subtitle {\n  margin: 0 0 22px;\n  text-align: center;\n  font-size: 15px;\n  color: hsl(var(--hue) 40% 70%);\n  font-weight: 600;\n}\n\n.meter {\n  margin-bottom: 26px;\n}\n\n.meter-bar {\n  height: 8px;\n  border-radius: 4px;\n  background: #232833;\n  overflow: hidden;\n}\n\n.meter-bar i {\n  display: block;\n  height: 100%;\n  width: 0%;\n  border-radius: 4px;\n  background: var(--body);\n  transition: width 0.6s ease;\n}\n\n.meter-labels {\n  display: flex;\n  justify-content: space-between;\n  margin-top: 7px;\n  font-size: 12px;\n  color: #8b95a8;\n  font-variant-numeric: tabular-nums;\n}\n\n.panel {\n  background: #1a1e27;\n  border: 1px solid #262c38;\n  border-radius: 14px;\n  padding: 16px 18px;\n  margin-bottom: 14px;\n}\n\n.panel h2 {\n  margin: 0 0 12px;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: 0.1em;\n  color: #7c8699;\n  text-transform: uppercase;\n}\n\n/*\n * 束の名前。**節の見出しより格を上に見せる** ── 同じ大きさだと、\n * 束なのか節なのかが読めない。左の線で「ここから下がひとまとまり」を出す。\n */\n.group-head {\n  margin: 26px 0 10px;\n  padding-left: 10px;\n  border-left: 2px solid hsl(var(--hue) 45% 46%);\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  color: #aeb8c9;\n}\n\n/* いちばん上だけは詰める（:first-of-type だと #subtitle に取られる） */\n.meter + .group-head {\n  margin-top: 18px;\n}\n\n.rows {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.row {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  font-size: 15px;\n}\n\n.row span {\n  color: #a8b2c4;\n}\n\n.row b {\n  font-weight: 700;\n  font-variant-numeric: tabular-nums;\n}\n\n/*\n * 注記つきの行。**数字の下に「何を数えたか」を敷く。**\n * flex のままだと注記が横に並んでしまうので、ここだけ格子に組み替える。\n */\n.row.has-note {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  column-gap: 12px;\n  align-items: baseline;\n}\n\n.row.has-note > b {\n  grid-column: 2;\n  justify-self: end;\n}\n\n/*\n * 2 行目は左に注記、右に添え数字（「平均の 1.3 倍」）。**行を明示的に置く**\n * ── 自動配置に任せると添え数字が 2 行目、注記が 3 行目に落ちて、1 行のはずの\n * ものが 3 行ぶんの高さになる。\n */\n.row-sub {\n  grid-column: 2;\n  grid-row: 2;\n  justify-self: end;\n  font-style: normal;\n  font-size: 11px;\n  color: hsl(var(--hue) 40% 62%);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n\n.row-note {\n  grid-column: 1;\n  grid-row: 2;\n  margin-top: 1px;\n  font-size: 11px;\n  line-height: 1.5;\n  color: #7b8496;\n}\n\n/* ---- おぼえた技 ---- */\n.skills {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.skill {\n  display: grid;\n  grid-template-columns: auto auto 1fr;\n  column-gap: 8px;\n  align-items: baseline;\n  font-size: 15px;\n}\n\n.skill b {\n  font-weight: 700;\n}\n\n.skill i {\n  font-style: normal;\n  color: var(--body);\n  font-size: 13px;\n  letter-spacing: 0.08em;\n}\n\n/* 次の段位まであと何回。数字は右端に寄せて、名前の並びを乱さない */\n.skill em {\n  justify-self: end;\n  font-style: normal;\n  font-size: 12px;\n  color: #7c8699;\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n\n/* いま実際に効いている数字。**効き目のほうが本体**なので、説明より目立たせる */\n.skill span.is-effect {\n  color: hsl(140 50% 68%);\n  font-weight: 700;\n}\n\n/* 説明は全列ぶち抜きの 2 行目。名前と星の下にぶら下げる */\n.skill span {\n  grid-column: 1 / -1;\n  margin-top: 2px;\n  font-size: 12px;\n  color: #8b95a8;\n  line-height: 1.5;\n}\n\n/* まだ生えていない技。「何をすれば生えるか」だけ見せる */\n.skill.locked b,\n.skill.locked i {\n  color: #5d6675;\n}\n\n/* ---- 働き方の内訳 ---- */\n.bars {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-bottom: 12px;\n}\n\n.bar {\n  display: grid;\n  grid-template-columns: 4.5em 1fr auto;\n  align-items: center;\n  column-gap: 10px;\n  font-size: 14px;\n}\n\n.bar b {\n  font-weight: 700;\n}\n\n.bar i {\n  display: block;\n  height: 8px;\n  border-radius: 4px;\n  background: #232833;\n  overflow: hidden;\n}\n\n.bar i span {\n  display: block;\n  height: 100%;\n  border-radius: 4px;\n  transition: width 0.6s ease;\n}\n\n.bar em {\n  font-style: normal;\n  font-size: 12px;\n  color: #8b95a8;\n  font-variant-numeric: tabular-nums;\n}\n\n/* ---- 渡り歩いた職 ---- */\n.jobs-note {\n  margin: 0 0 8px;\n  font-size: 13px;\n  color: #8b95a8;\n}\n\n.jobs {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-bottom: 14px;\n}\n\n/* 通ってきた順に左から。いまの名前が最後に来る */\n.job {\n  display: inline-flex;\n  align-items: baseline;\n  gap: 6px;\n  padding: 5px 10px;\n  border-radius: 999px;\n  border: 1px solid hsl(var(--hue) var(--sat) 40%);\n  background: hsl(var(--hue) var(--sat) 20% / 0.35);\n  font-size: 13px;\n  font-weight: 700;\n  color: hsl(var(--hue) var(--sat) 76%);\n}\n\n.job em {\n  font-style: normal;\n  font-weight: 400;\n  font-size: 11px;\n  color: #6f7a8c;\n}\n\n/* その職としての位。名前の隣に置く ── 全体のレベルとは別物 */\n.job-level {\n  text-decoration: none;\n  font-size: 11px;\n  font-weight: 800;\n  color: hsl(var(--hue) 55% 72%);\n  font-variant-numeric: tabular-nums;\n}\n\n/* ---- 型 ---- */\n.panel h2 #persona-code {\n  font-size: 12px;\n  font-weight: 400;\n  color: #6f7a8c;\n}\n\n.persona-name {\n  margin: 0 0 4px;\n  font-size: 20px;\n  font-weight: 700;\n  color: hsl(var(--hue) var(--sat) 72%);\n}\n\n.axes {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  margin-top: 14px;\n}\n\n.axis {\n  display: grid;\n  grid-template-columns: 5.5em 1fr 5.5em;\n  align-items: center;\n  column-gap: 8px;\n  font-size: 13px;\n}\n\n.axis b {\n  font-weight: 400;\n  color: #6f7a8c;\n}\n\n/* 寄っているほうだけ明るくする。両方同じ濃さだと、どっちの人か読めない */\n.axis b.on {\n  font-weight: 700;\n  color: var(--body);\n}\n\n.axis b:last-of-type {\n  text-align: right;\n}\n\n.axis i {\n  position: relative;\n  display: block;\n  height: 4px;\n  border-radius: 2px;\n  background: #232833;\n}\n\n/* 目盛りの真ん中が境目。端に寄るほど、その傾向が強い */\n.axis i::after {\n  content: '';\n  position: absolute;\n  left: 50%;\n  top: -3px;\n  width: 1px;\n  height: 10px;\n  background: #39404e;\n}\n\n.axis i span {\n  position: absolute;\n  top: 50%;\n  width: 10px;\n  height: 10px;\n  margin-left: -5px;\n  border-radius: 50%;\n  background: hsl(var(--hue) var(--sat) 66%);\n  transform: translateY(-50%);\n  transition: left 0.5s ease;\n}\n\n/* 寄っているほうの意味。**軸の名前より、こちらのほうが先に読まれていい** */\n.axis-meaning {\n  grid-column: 1 / -1;\n  margin-top: 5px;\n  text-decoration: none;\n  font-size: 12.5px;\n  color: #c2cbd9;\n}\n\n.axis-meaning:empty {\n  display: none;\n}\n\n.axis em {\n  grid-column: 1 / -1;\n  margin-top: 2px;\n  font-style: normal;\n  font-size: 11px;\n  color: #5d6675;\n}\n\n/* 5 軸目（リズム）は 4 文字の後ろに付くぶん。線で切って別物に見せる */\n.axis.suffix {\n  padding-top: 12px;\n  border-top: 1px solid #232833;\n}\n\n/* まだ母数が足りない軸は、そう見えるように薄くする */\n.axis.unknown {\n  opacity: 0.4;\n}\n\n/* ---- ここ 2 週間 ---- */\n.trail {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: 3px;\n  height: 76px;\n}\n\n.trail-day {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 4px;\n  min-width: 0;\n}\n\n.trail-day i {\n  display: block;\n  width: 100%;\n  max-width: 18px;\n  border-radius: 3px;\n  background: hsl(var(--hue) var(--sat) 62%);\n  transition: height 0.5s ease;\n}\n\n/* 働かなかった日も列を残す。詰めると休んだ日が無かったことになる */\n.trail-day.is-empty i {\n  background: #232833;\n}\n\n/* 今日だけ縁を付ける。色を変えるより、位置が分かるほうが要る */\n.trail-day.is-today i {\n  outline: 1px solid hsl(var(--hue) var(--sat) 78%);\n  outline-offset: 1px;\n}\n\n.trail-day em {\n  font-style: normal;\n  font-size: 10px;\n  color: #6f7a8c;\n  font-variant-numeric: tabular-nums;\n}\n\n.trail-note {\n  margin: 10px 0 0;\n  font-size: 13px;\n  color: #8b95a8;\n}\n\n/* ---- 実績 ---- */\n.panel h2 span {\n  color: var(--body);\n  font-variant-numeric: tabular-nums;\n}\n\n/*\n * **獲った称号は 2 列に敷く。** 26 個を説明つきで縦に並べると、それだけで\n * 画面の半分が称号になる。名前と日付だけ見せて、読みたいものだけ開く。\n */\n.achievements {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(168px, 1fr));\n  gap: 6px;\n}\n\n.achievement {\n  padding: 7px 10px;\n  border-radius: 8px;\n  background: #1b2029;\n  font-size: 14px;\n}\n\n.achievement summary {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 8px;\n  cursor: pointer;\n  /* 既定の三角は出さない（2 列に並ぶので、印より詰まっているほうが読みやすい） */\n  list-style: none;\n}\n\n.achievement summary::-webkit-details-marker {\n  display: none;\n}\n\n.achievement b {\n  font-weight: 700;\n  /* 名前は途中で折らない。「はじめの一 / 歩」になると読めない */\n  word-break: keep-all;\n}\n\n.achievement time {\n  font-size: 11px;\n  color: #7c8699;\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n\n.achievement > span {\n  display: block;\n  margin-top: 5px;\n  font-size: 12px;\n  color: #8b95a8;\n  line-height: 1.55;\n}\n\n/*\n * うまくいかなかったほう。**沈めるのではなく、別の色にする**\n * ── 薄くすると「劣ったもの」に見えるが、これは並びとしては同じ重さ。\n */\n.achievement.rough {\n  background: hsl(20 18% 17%);\n}\n.achievement.rough b {\n  color: hsl(20 60% 76%);\n}\n\n/* まだのものは名前だけ、まとめて 1 行。説明も進捗も付けない */\n.achievement-rest {\n  grid-column: 1 / -1;\n  margin: 6px 0 0;\n  font-size: 11.5px;\n  line-height: 1.7;\n  color: #5d6675;\n}\n\n/* ---- 留守のあいだに ---- */\n.finds {\n  display: flex;\n  /* 2 行になったので横並びをやめる。丸い札のままだと注記が折り返せない */\n  flex-direction: column;\n  gap: 8px;\n}\n\n/*\n * 拾い物。**名前 + 相棒の観察記録の 2 行。**\n *\n * 名前だけを丸い札で並べていたが、それだと「へえ」で終わる ── 面白いのは\n * 大層な名前のほうではなく、**それが何か知らないまま真面目に観察している落差**\n * （ピクミンのお宝の書き方）。一言のほうが本体なので、札をやめて行にした。\n */\n.find {\n  display: block;\n  width: 100%;\n  padding: 9px 13px;\n  border-radius: 10px;\n  background: #232833;\n  font-size: 13px;\n  color: #c3ccdb;\n}\n\n.find b {\n  display: block;\n  font-weight: 600;\n}\n\n.find small {\n  display: block;\n  margin-top: 2px;\n  font-size: 12px;\n  line-height: 1.7;\n  color: #8b93a5;\n}\n\n\n/* ---- 今日の一戦 ---- */\n.battle-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 10px;\n  font-size: 15px;\n  margin-bottom: 12px;\n}\n\n.battle-result {\n  font-weight: 800;\n  white-space: nowrap;\n}\n.battle-result.you {\n  color: hsl(140 60% 62%);\n}\n.battle-result.foe {\n  color: hsl(0 60% 66%);\n}\n.battle-result.draw {\n  color: #8b95a8;\n}\n\n/* 手応え。相手の強さは数字で出さないので、ここが唯一の物差しになる */\n.battle-impression {\n  margin: -4px 0 12px;\n  font-size: 13px;\n  color: #a8b2c4;\n}\n\n.battle-log {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  font-size: 13px;\n  line-height: 1.5;\n  color: #a8b2c4;\n  font-variant-numeric: tabular-nums;\n}\n\n/* 決着の行だけは目で拾えるようにする */\n.battle-log li:last-child {\n  color: #e8ecf4;\n  font-weight: 700;\n}\n\n.battle-note {\n  margin: 12px 0 0;\n  font-size: 11px;\n  color: #5d6675;\n  line-height: 1.5;\n}\n\n#battle-panel.empty .battle-top {\n  margin-bottom: 0;\n  color: #8b95a8;\n}\n\n#foot {\n  margin: 24px 0 0;\n  text-align: center;\n  font-size: 11px;\n  color: #5d6675;\n  line-height: 1.6;\n}\n\n/* 通信が切れたら黙って古い数字を出し続けるのではなく、はっきり見せる */\nbody.stale main {\n  opacity: 0.45;\n  transition: opacity 0.3s ease;\n}\n\n/* ---- 六角形の能力値 ---- */\n/*\n * **形が読めることを優先する。** 真ん中の輪（is-average）が「同じレベルの\n * 平均」で、そこから外に出ているところがこの子の得意。数字だけ並べても、\n * それが高いのか低いのかは分からない。\n */\n.hex {\n  display: block;\n  width: 100%;\n  max-width: 260px;\n  /*\n   * **縦を明示する。** viewBox しか無い SVG の高さの決め方はブラウザで揃って\n   * いなくて、既定の 150px に落ちると図が潰れる。比を書いておけばどこでも同じ。\n   */\n  aspect-ratio: 200 / 190;\n  height: auto;\n  margin: 0 auto 10px;\n  overflow: visible;\n}\n\n/* 節が転けたときだけ出る。**黙って消えるより、理由が出ているほうがいい** */\n.panel-error {\n  margin: 8px 0 0;\n  font-size: 12px;\n  line-height: 1.6;\n  color: hsl(6 70% 70%);\n  word-break: break-word;\n}\n\n.hex-ring {\n  fill: none;\n  stroke: #2a3040;\n  stroke-width: 1;\n}\n\n/* 平均の輪だけ少し濃く。ここを基準に「外に出ている / 凹んでいる」を読む */\n.hex-ring.is-average {\n  stroke: #3d4557;\n  stroke-dasharray: 3 3;\n}\n\n.hex-spoke {\n  stroke: #232a38;\n  stroke-width: 1;\n}\n\n.hex-shape {\n  fill: hsl(var(--hue) 55% 55% / 0.28);\n  stroke: hsl(var(--hue) 65% 62%);\n  stroke-width: 2;\n  stroke-linejoin: round;\n  /* 伸び縮みが見えるように。跳ねさせない ── 常駐の画面で暴れると疲れる */\n  transition: points 0.6s ease;\n}\n\n.hex-label {\n  fill: #8b93a5;\n  font-size: 12px;\n  font-weight: 700;\n  transition: fill 0.4s ease;\n}\n\n/* 上がったところは緑、下がったところは赤。数秒で戻る */\n.hex-label.up,\n.row.up b {\n  fill: hsl(140 62% 62%);\n  color: hsl(140 62% 62%);\n}\n\n.hex-label.down,\n.row.down b {\n  fill: hsl(0 62% 66%);\n  color: hsl(0 62% 66%);\n}\n\n.row.up b::after {\n  content: ' ▲';\n  font-size: 10px;\n}\n\n.row.down b::after {\n  content: ' ▼';\n  font-size: 10px;\n}\n\n/* ---- ダンジョン ---- */\n#dungeon-floor {\n  color: hsl(var(--hue) 60% 70%);\n  font-variant-numeric: tabular-nums;\n}\n\n.gear {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin-bottom: 14px;\n}\n\n.gear-item {\n  display: grid;\n  grid-template-columns: 22px 1fr auto auto;\n  align-items: baseline;\n  gap: 8px;\n  padding: 7px 10px;\n  border-radius: 8px;\n  background: #1b2029;\n  font-size: 13px;\n}\n\n/* 枠（攻・守・速）の 1 文字 */\n.gear-item i {\n  font-style: normal;\n  font-weight: 800;\n  color: #6f7889;\n  text-align: center;\n}\n\n.gear-item b {\n  font-weight: 600;\n  color: #e2e8f2;\n}\n\n.gear-item em {\n  font-style: normal;\n  font-size: 11px;\n  color: #8b93a5;\n}\n\n.gear-item span {\n  font-weight: 800;\n  color: hsl(140 55% 66%);\n  font-variant-numeric: tabular-nums;\n  font-size: 12px;\n  white-space: nowrap;\n}\n\n/* 宿り ── 装備の中身。ぶら下げて、装備の一部だと分かるようにする */\n.imbue {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin: -2px 0 0 30px;\n  padding: 3px 10px;\n  border-left: 2px solid #2f3644;\n  font-size: 12px;\n}\n\n.imbue b {\n  font-weight: 700;\n  color: hsl(280 45% 76%);\n  white-space: nowrap;\n}\n\n.imbue span {\n  color: #7d8697;\n}\n\n/*\n * 位の色。**灰 → 緑 → 青 → 紫 → 金**。\n *\n * 呼び名（コモン〜レジェンド）を読まなくても、色だけで上下が分かる並びにする\n * ── ゲームで何十年も使われている順番なので、説明が要らない。\n * 系統色（--hue）には寄せない。系統で色が変わると、位の色が人によって別物になる。\n */\n:root {\n  --r-uncommon: 145;\n  --r-rare: 210;\n  --r-mystic: 285;\n  --r-legend: 42;\n}\n\n.gear-item.r-uncommon {\n  background: hsl(var(--r-uncommon) 22% 17%);\n}\n.gear-item.r-uncommon b,\n.gear-item.r-uncommon em {\n  color: hsl(var(--r-uncommon) 55% 74%);\n}\n\n.gear-item.r-rare {\n  background: hsl(var(--r-rare) 32% 20%);\n}\n.gear-item.r-rare b,\n.gear-item.r-rare em {\n  color: hsl(var(--r-rare) 75% 80%);\n}\n\n.gear-item.r-mystic {\n  background: hsl(var(--r-mystic) 32% 21%);\n}\n.gear-item.r-mystic b,\n.gear-item.r-mystic em {\n  color: hsl(var(--r-mystic) 70% 82%);\n}\n\n/* いちばん上だけ縁を光らせる。**ここだけは拾った瞬間に気づいてほしい** */\n.gear-item.r-legend {\n  background: hsl(var(--r-legend) 38% 20%);\n  box-shadow: inset 0 0 0 1px hsl(var(--r-legend) 65% 46%);\n}\n.gear-item.r-legend b,\n.gear-item.r-legend em {\n  color: hsl(var(--r-legend) 88% 76%);\n}\n\n/* 拾い物の粒も同じ色で。並べたときに、良い日かどうかが一目で分かる */\n.find.r-uncommon {\n  background: hsl(var(--r-uncommon) 24% 22%);\n  color: hsl(var(--r-uncommon) 55% 78%);\n}\n.find.r-rare {\n  background: hsl(var(--r-rare) 36% 25%);\n  color: hsl(var(--r-rare) 78% 84%);\n  font-weight: 700;\n}\n.find.r-mystic {\n  background: hsl(var(--r-mystic) 36% 26%);\n  color: hsl(var(--r-mystic) 72% 85%);\n  font-weight: 700;\n}\n.find.r-legend {\n  background: hsl(var(--r-legend) 42% 24%);\n  color: hsl(var(--r-legend) 90% 80%);\n  font-weight: 800;\n  box-shadow: inset 0 0 0 1px hsl(var(--r-legend) 65% 48%);\n}\n\n/* 拾った階を、小さく後ろに添える */\n#dungeon-finds .find em {\n  font-style: normal;\n  margin-left: 6px;\n  font-size: 10px;\n  opacity: 0.6;\n}\n\n/* ---- 抜けてきた主 ---- */\n/*\n * **通過点であって、集めるものではない。** まだ会っていない主は出さないので、\n * ここは「そこまで潜った」の言い換えでしかない。並びは新しい順。\n */\n.bosses {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin-bottom: 14px;\n}\n\n.boss {\n  display: grid;\n  grid-template-columns: 38px 1fr;\n  gap: 4px 10px;\n  padding: 7px 10px;\n  border-radius: 8px;\n  background: #191d26;\n  font-size: 13px;\n}\n\n/* 階の数字。ここが道の目盛りになる */\n.boss i {\n  grid-row: 1 / 3;\n  align-self: center;\n  font-style: normal;\n  font-weight: 800;\n  font-size: 15px;\n  text-align: right;\n  color: hsl(var(--hue) 55% 62%);\n  font-variant-numeric: tabular-nums;\n}\n\n.boss b {\n  font-weight: 700;\n  color: #dfe5f0;\n}\n\n.boss span {\n  font-size: 11px;\n  color: #798193;\n}\n\n/* ------------------------------------------------------------------ *\n * 目次（左カラム）\n *\n * 節が 11 個まで増えて、縦スクロールだけでは端から端まで遠くなった。\n * **中身は隠さない** ── ここは飛ぶための目次で、節を畳んだり切り替えたり\n * はしない（隠すと「そこに何があるか」が消える）。\n * ------------------------------------------------------------------ */\n.menu-button {\n  position: fixed;\n  top: calc(12px + env(safe-area-inset-top));\n  left: 12px;\n  z-index: 30;\n  display: grid;\n  gap: 4px;\n  width: 42px;\n  height: 42px;\n  padding: 11px 10px;\n  border: 0;\n  border-radius: 12px;\n  background: hsl(var(--hue) 18% 16% / 0.82);\n  backdrop-filter: blur(6px);\n  cursor: pointer;\n  /* 指で押せる大きさ。40px を切ると押し損ねる */\n  -webkit-tap-highlight-color: transparent;\n}\n\n.menu-button span {\n  display: block;\n  height: 2px;\n  border-radius: 2px;\n  background: hsl(var(--hue) 30% 82%);\n  transition: transform 0.2s ease, opacity 0.2s ease;\n}\n\n/* 開いている間は × に */\n.menu-button[aria-expanded='true'] span:nth-child(1) {\n  transform: translateY(6px) rotate(45deg);\n}\n.menu-button[aria-expanded='true'] span:nth-child(2) {\n  opacity: 0;\n}\n.menu-button[aria-expanded='true'] span:nth-child(3) {\n  transform: translateY(-6px) rotate(-45deg);\n}\n\n.scrim {\n  position: fixed;\n  inset: 0;\n  z-index: 20;\n  background: #0b0d12cc;\n}\n\n.drawer {\n  position: fixed;\n  top: 0;\n  left: 0;\n  bottom: 0;\n  z-index: 25;\n  width: min(74vw, 260px);\n  padding: calc(64px + env(safe-area-inset-top)) 0 24px;\n  background: #171b23;\n  border-right: 1px solid #252b37;\n  /* 閉じている間は左に逃がす。display:none にすると開く動きが出ない */\n  transform: translateX(-102%);\n  transition: transform 0.24s cubic-bezier(0.4, 0, 0.2, 1);\n  overflow-y: auto;\n}\n\n.drawer.open {\n  transform: translateX(0);\n}\n\n.drawer-head {\n  padding: 0 18px 14px;\n  border-bottom: 1px solid #252b37;\n  margin-bottom: 8px;\n}\n\n.drawer-head b {\n  display: block;\n  font-size: 16px;\n  color: #e8ecf4;\n}\n\n.drawer-head em {\n  font-style: normal;\n  font-size: 12px;\n  color: hsl(var(--hue) 55% 68%);\n  font-variant-numeric: tabular-nums;\n}\n\n.drawer ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.drawer a {\n  display: block;\n  padding: 13px 18px;\n  color: #c3ccdb;\n  text-decoration: none;\n  font-size: 14px;\n}\n\n.drawer a:active {\n  background: hsl(var(--hue) 30% 22%);\n}\n\n/* 束の名前。ここは飛び先ではないので、押せるように見せない */\n.drawer-group {\n  padding: 14px 18px 5px;\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.16em;\n  color: #5d6677;\n}\n\n.drawer-group:first-child {\n  padding-top: 4px;\n}\n\n/* 目次の中身は画面の外に出さない ── 開いたときに全部見えるようにする */\n@media (max-height: 560px) {\n  .drawer a {\n    padding: 9px 18px;\n  }\n\n  .drawer-group {\n    padding: 9px 18px 3px;\n  }\n}\n\n/* ボタンのぶんだけ、頭を空ける（キャラと重ならないように） */\nmain {\n  padding-top: calc(58px + env(safe-area-inset-top));\n}\n" },
  "pet-svg.js": { type: "text/javascript; charset=utf-8", body: "/**\n * キャラの絵。オーバーレイとスマホ用ページの両方がここから読む。\n *\n * 絵を 2 箇所に置くと必ずズレるので、markup はこのファイルだけに持つ。\n * ES モジュールにしていないのは、file:// のオーバーレイと http:// のスマホ用\n * ページの両方から同じ書き方（<script src>）で読めるようにするため。\n */\nwindow.AIPET_SVG = `\n<svg id=\"pet\" viewBox=\"0 14 200 200\" aria-hidden=\"true\">\n  <ellipse id=\"shadow\" cx=\"100\" cy=\"168\" rx=\"44\" ry=\"7.5\" />\n\n  <!-- オーラは体より奥。creature より前に置くと胴体を横切る -->\n  <g id=\"aura\">\n    <ellipse cx=\"100\" cy=\"122\" rx=\"66\" ry=\"53\" />\n  </g>\n\n  <g id=\"creature\">\n    <!--\n      装備のうち、**手に持つもの・脇に付くもの**は体より奥に置く。\n      前に置いていたとき、翼と盾が顔と胴に半透明で重なって、\n      **下の体が透けて見えていた**（実機の名刺でそれが一番目立った）。\n\n      奥に回せば、はみ出したぶんだけが見える ── **重ならないのではなく、\n      重なったところが隠れる**ので、装備が増えても顔が埋まらない。\n      体に「着る」もの（胴当て）だけは、下の #gear に残してある。\n\n      **触角と冠より、さらに奥。** 兜を後ろに置いたとき、兜が冠と触角の玉を\n      塗り潰していた ── 冠は Lv10 の節目で、装備より先にこの子のものなので、\n      隠されるのは装備のほう。\n    -->\n    <g id=\"gear-back\">\n      <!-- 攻 ── 右手に持つ -->\n      <g class=\"gear-atk\" id=\"gw-blade\">\n        <path class=\"grip\" d=\"M162 150 v14\" />\n        <path class=\"edge\" d=\"M158 150 l4 -58 l4 58 Z\" />\n        <path class=\"guard\" d=\"M152 150 h20\" />\n      </g>\n      <g class=\"gear-atk\" id=\"gw-axe\">\n        <path class=\"grip\" d=\"M164 100 v64\" />\n        <path class=\"edge\" d=\"M164 104 q 22 6 20 26 q -12 8 -20 -6 Z\" />\n      </g>\n      <g class=\"gear-atk\" id=\"gw-hammer\">\n        <path class=\"grip\" d=\"M164 104 v60\" />\n        <path class=\"edge\" d=\"M150 100 h28 v20 h-28 Z\" />\n      </g>\n      <g class=\"gear-atk\" id=\"gw-lance\">\n        <path class=\"grip\" d=\"M166 168 l-10 -70\" />\n        <path class=\"edge\" d=\"M156 98 l-5 -22 l11 18 Z\" />\n      </g>\n      <g class=\"gear-atk\" id=\"gw-bow\">\n        <path class=\"edge\" d=\"M158 96 q 26 34 0 68\" />\n        <path class=\"grip\" d=\"M158 96 L158 164\" />\n      </g>\n      <g class=\"gear-atk\" id=\"gw-whip\">\n        <path class=\"grip\" d=\"M162 148 v12\" />\n        <path class=\"edge\" d=\"M162 148 q 18 -8 12 -28 q -6 -16 8 -22\" />\n      </g>\n      <!-- 守 ── 左に構える、もしくは体に乗る -->\n      <g class=\"gear-def\" id=\"gw-shield\">\n        <path class=\"plate\" d=\"M20 108 h30 v26 q 0 16 -15 22 q -15 -6 -15 -22 Z\" />\n        <path class=\"trim\" d=\"M35 112 v40\" />\n      </g>\n      <g class=\"gear-def\" id=\"gw-cloak\">\n        <path class=\"plate\" d=\"M52 96 q -18 40 -6 74 q 20 8 26 -4 q -18 -34 -6 -68 Z\" />\n      </g>\n      <!-- 兜は頭に載る。奥に回すので、**頭より上に出たぶんだけ**が見える -->\n      <g class=\"gear-def\" id=\"gw-helm\">\n        <path class=\"plate\" d=\"M66 84 q 34 -26 68 0 q -6 10 -34 10 q -28 0 -34 -10 Z\" />\n        <path class=\"trim\" d=\"M100 62 v10\" />\n      </g>\n      <g class=\"gear-def\" id=\"gw-ward\">\n        <ellipse class=\"ring\" cx=\"100\" cy=\"122\" rx=\"63\" ry=\"50\" />\n        <ellipse class=\"ring2\" cx=\"100\" cy=\"122\" rx=\"68\" ry=\"54\" />\n      </g>\n      <!--\n        速さの 1 つめ。**足は描かない** ── 胴体だけの子に靴を履かせると、\n        それだけで別の生き物になる。代わりに、置いていった風の筋で速さを出す。\n      -->\n      <g class=\"gear-spd\" id=\"gw-dash\">\n        <path class=\"streak\" d=\"M34 138 h22\" />\n        <path class=\"streak\" d=\"M26 150 h30\" />\n        <path class=\"streak\" d=\"M38 162 h18\" />\n      </g>\n      <g class=\"gear-spd\" id=\"gw-wing\">\n        <path class=\"feather\" d=\"M48 106 q -30 12 -34 40 q 22 4 36 -14 Z\" />\n        <path class=\"feather\" d=\"M152 106 q 30 12 34 40 q -22 4 -36 -14 Z\" />\n      </g>\n      <g class=\"gear-spd\" id=\"gw-orb\">\n        <circle class=\"orb\" cx=\"168\" cy=\"88\" r=\"7\" />\n        <circle class=\"orb2\" cx=\"180\" cy=\"102\" r=\"4\" />\n      </g>\n      <g class=\"gear-spd\" id=\"gw-lens\">\n        <circle class=\"glass\" cx=\"150\" cy=\"96\" r=\"12\" />\n        <path class=\"grip\" d=\"M158 106 l12 14\" />\n      </g>\n    </g>\n\n    <!-- Lv3 で生える触角。系統が確定した合図でもある -->\n    <g id=\"antenna\">\n      <path d=\"M100 88 Q 95 62 108 52\" />\n      <circle cx=\"110\" cy=\"49\" r=\"6.5\" />\n    </g>\n\n    <!-- Lv10 で乗る冠 -->\n    <g id=\"crown\">\n      <path d=\"M76 78 L83 58 L100 70 L117 58 L124 78 Z\" />\n    </g>\n\n    <path\n      id=\"body\"\n      d=\"M 100 82 C 142 82 156 108 156 134 C 156 156 130 166 100 166 C 70 166 44 156 44 134 C 44 108 58 82 100 82 Z\"\n    />\n\n    <!--\n      スキンの模様（src/core/skins.js）。**既定では全部消えている。**\n      体の形に切り抜くので、どの模様を足しても輪郭からはみ出さない。\n\n      顔より奥・体より手前。顔に掛けると、型（persona.js）が決める目つきと\n      口元が模様に埋もれる ── **顔つきはスキンで買えない**（§8c）。\n    -->\n    <!-- 体の上のつや。丸みを 1 枚で出す（クラスで色を付ける ── 直書きしない） -->\n    <path id=\"sheen\" d=\"M 72 92 C 85 87 115 87 128 92 C 115 84 85 84 72 92 Z\" />\n\n    <g id=\"skin-texture\" clip-path=\"url(#body-clip)\">\n      <clipPath id=\"body-clip\">\n        <path d=\"M 100 82 C 142 82 156 108 156 134 C 156 156 130 166 100 166 C 70 166 44 156 44 134 C 44 108 58 82 100 82 Z\" />\n      </clipPath>\n\n      <!-- 墨：紙目のような細い縞 -->\n      <g class=\"tex\" id=\"tex-grain\">\n        <path d=\"M44 96 H156 M44 112 H156 M44 128 H156 M44 144 H156 M44 160 H156\" />\n      </g>\n\n      <!-- 熾火：下から上に抜ける熱 -->\n      <g class=\"tex\" id=\"tex-ember\">\n        <ellipse cx=\"100\" cy=\"168\" rx=\"52\" ry=\"26\" />\n        <ellipse cx=\"100\" cy=\"176\" rx=\"34\" ry=\"20\" />\n      </g>\n\n      <!-- 霜：角のある結晶 -->\n      <g class=\"tex\" id=\"tex-frost\">\n        <path d=\"M62 96 l10 10 l-10 10 M138 140 l-10 10 l10 10 M92 88 l8 8 l-8 8\" />\n      </g>\n\n      <!-- 宵：夜空の粒 -->\n      <g class=\"tex\" id=\"tex-stars\">\n        <circle cx=\"66\" cy=\"104\" r=\"2\" />\n        <circle cx=\"132\" cy=\"98\" r=\"1.6\" />\n        <circle cx=\"146\" cy=\"132\" r=\"2.2\" />\n        <circle cx=\"58\" cy=\"140\" r=\"1.8\" />\n        <circle cx=\"104\" cy=\"92\" r=\"1.4\" />\n        <circle cx=\"120\" cy=\"158\" r=\"1.6\" />\n      </g>\n    </g>\n\n    <g id=\"face\">\n      <g class=\"eye\" transform=\"translate(78 128)\">\n        <circle class=\"eyeball\" r=\"10.5\" />\n        <circle class=\"pupil\" r=\"4.5\" />\n        <!--\n          光。**これ 1 個で顔つきが変わる** ── 瞳が真っ黒のままだと、\n          どんなに形を丸くしても「点」に見える。左上に寄せるのは、\n          そこに光源があると読ませるため（両目とも同じ側に置く）。\n        -->\n        <circle class=\"glint\" cx=\"-2.8\" cy=\"-2.8\" r=\"2.1\" />\n        <path class=\"lid\" d=\"M-11 0 Q 0 7 11 0\" />\n      </g>\n      <g class=\"eye\" transform=\"translate(122 128)\">\n        <circle class=\"eyeball\" r=\"9\" />\n        <circle class=\"pupil\" r=\"4\" />\n        <circle class=\"glint\" cx=\"-2.6\" cy=\"-2.6\" r=\"1.9\" />\n        <path class=\"lid\" d=\"M-10 0 Q 0 6 10 0\" />\n      </g>\n      <path id=\"mouth\" d=\"M94 145 Q 100 149 106 145\" />\n\n      <!--\n        頬の赤み。**顔つきは型が決める**ので、形には触らない ── 色を薄く\n        敷くだけ。系統色（--hue）に寄せてあるので、系統が決まるまでは\n        ほとんど出ない（無彩色の子に頬紅だけ乗ると浮く）。\n      -->\n      <g id=\"blush\">\n        <ellipse cx=\"72\" cy=\"138\" rx=\"8\" ry=\"4.5\" />\n        <ellipse cx=\"128\" cy=\"138\" rx=\"8\" ry=\"4.5\" />\n      </g>\n    </g>\n\n    <!--\n      使い込み ── 一緒にいた長さぶんの傷。**性能には 1 も効かない**（見た目だけ）。\n      体の形に切り抜くので、どれだけ増やしても輪郭からはみ出さない。\n    -->\n    <g id=\"patina\" clip-path=\"url(#body-clip)\">\n      <path class=\"scar\" id=\"scar-1\" d=\"M120 96 l16 12\" />\n      <path class=\"scar\" id=\"scar-2\" d=\"M58 132 l14 -9\" />\n      <path class=\"scar\" id=\"scar-3\" d=\"M104 158 l20 4\" />\n      <path class=\"scar\" id=\"scar-4\" d=\"M66 106 l10 12\" />\n      <path class=\"scar\" id=\"scar-5\" d=\"M138 148 l-12 8\" />\n      <!-- 縁の欠け。1 年もの -->\n      <path class=\"chip\" id=\"chip-1\" d=\"M150 118 l10 -6 l2 12 Z\" />\n      <path class=\"chip\" id=\"chip-2\" d=\"M48 142 l-10 4 l1 -12 Z\" />\n    </g>\n\n    <!--\n      顔まわりの小物。**顔より手前**（目と口の上に乗る）。\n\n      **これは買えるスキンとは別物。** どれも作業ログから生えているので、\n      目つき・口元と出どころが同じ ── だから顔に掛かってよい（買えるスキンの\n      ほうは、いままでどおり顔に一切触らない。DESIGN.md §8c）。\n\n      顔は 目 (82,122) / (118,122)・口 (100,142) の周り。\n      **同じ場所のものは同時に出ない**（appearance.js が段の大きいほうだけ返す）。\n    -->\n    <g id=\"wear\">\n      <!-- 口元 ── 一緒に過ごした長さで伸びる -->\n      <g class=\"worn\" id=\"ac-stubble\">\n        <path class=\"hair\" d=\"M84 150 q 16 10 32 0 q -4 12 -16 12 q -12 0 -16 -12 Z\" />\n      </g>\n      <g class=\"worn\" id=\"ac-moustache\">\n        <path class=\"hair\" d=\"M78 134 q 20 -8 22 3 q 2 -11 22 -3 q -8 11 -22 8 q -14 3 -22 -8 Z\" />\n      </g>\n      <g class=\"worn\" id=\"ac-beard\">\n        <path class=\"hair\" d=\"M78 134 q 20 -8 22 3 q 2 -11 22 -3 q -8 11 -22 8 q -14 3 -22 -8 Z\" />\n        <path class=\"hair\" d=\"M80 150 q 20 13 40 0 q -3 18 -20 18 q -17 0 -20 -18 Z\" />\n      </g>\n\n      <!-- 目元 ── 眼鏡は学者、サングラスは夜目から -->\n      <g class=\"worn\" id=\"ac-glasses\">\n        <circle class=\"rim\" cx=\"78\" cy=\"128\" r=\"14.5\" />\n        <circle class=\"rim\" cx=\"122\" cy=\"128\" r=\"14.5\" />\n        <path class=\"rim\" d=\"M93 128 h14\" />\n      </g>\n      <!--\n        サングラスは**中を透かさない**（style.css）。透かしていたときは、\n        レンズの下から白目と瞳がはみ出して「掛けそこねている」ようにしか\n        見えなかった ── レンズは角の立った形、目は丸なので、大きさを\n        合わせにいっても必ずどこかが出る。掛けている間は目のほうを消す。\n\n        代わりに**斜めの光を 1 本入れる。** 塗り潰しただけだと、顔に黒い穴が\n        2 つ空いているように見える（瞳の光と同じ話で、光が 1 個あるかどうかで\n        「物」に見えるかが決まる）。\n      -->\n      <g class=\"worn\" id=\"ac-shades\">\n        <path class=\"lens\" d=\"M65 121 h29 v13 q -15 7 -29 0 Z\" />\n        <path class=\"lens\" d=\"M106 121 h29 v13 q -15 7 -29 0 Z\" />\n        <path class=\"shine\" d=\"M73 122 h5 l-6 12 h-5 Z\" />\n        <path class=\"shine\" d=\"M114 122 h5 l-6 12 h-5 Z\" />\n        <path class=\"rim\" d=\"M94 125 h12 M65 121 h70\" />\n      </g>\n\n      <!-- 首 ── 席に着いた回数 -->\n      <!-- 口に掛けない。口元は型（persona.js）が決めるものなので、隠すと誰か分からなくなる -->\n      <g class=\"worn\" id=\"ac-scarf\">\n        <path class=\"cloth\" d=\"M70 158 q 30 10 60 0 q 1 9 -6 12 q -24 8 -48 0 q -7 -3 -6 -12 Z\" />\n        <path class=\"cloth\" d=\"M124 169 q 10 8 7 18 q -9 1 -12 -6 Z\" />\n      </g>\n\n      <!-- 頬 ── 空振りの数。**責める言葉は使わない**（やってきた証のほう） -->\n      <g class=\"worn\" id=\"ac-bandage\">\n        <path class=\"patch\" d=\"M132 138 l14 -8 l6 10 l-14 8 Z\" />\n      </g>\n\n      <!-- 耳 ── 称号の数 -->\n      <g class=\"worn\" id=\"ac-earring\">\n        <path class=\"wire\" d=\"M50 126 v8\" />\n        <circle class=\"stud\" cx=\"50\" cy=\"139\" r=\"6\" />\n      </g>\n    </g>\n\n    <!--\n      ケガ ── **直前の一戦に負けたときだけ、しばらく。**（appearance.js の hurtFor）\n\n      1 時間で勝手に治る。手当ての操作は無いし、そのあいだ弱ってもいない\n      ── 数字には 1 も効かない（DESIGN.md §3「世話される側にしない」）。\n\n      **絆創膏は左の頬**（x=62 あたり）。称号の絆創膏（ac-bandage）は\n      右の頬（x=132）なので、両方出ても重ならない。\n    -->\n    <g id=\"hurt\">\n      <!-- 深い（負けた直後） -->\n      <g class=\"wound\" id=\"hurt-deep\">\n        <path class=\"plaster\" d=\"M56 148 l16 -9 l6 10 l-16 9 Z\" />\n        <path class=\"plaster-cross\" d=\"M62 150 l7 -4\" />\n        <path class=\"plaster-cross\" d=\"M64 144 l3 9\" />\n        <!-- 擦り傷は体の形で切り抜く。輪郭からはみ出すと貼り紙に見える -->\n        <g clip-path=\"url(#body-clip)\">\n          <path class=\"graze\" d=\"M106 160 l16 3\" />\n          <path class=\"graze\" d=\"M114 152 l13 4\" />\n        </g>\n      </g>\n      <!-- 浅い（治りかけ）── 絆創膏だけ残る -->\n      <g class=\"wound\" id=\"hurt-mild\">\n        <path class=\"plaster\" d=\"M58 147 l14 -8 l5 9 l-14 8 Z\" />\n      </g>\n    </g>\n\n    <!--\n      装備と、育ちの段。**どれも既定では消えている**（CSS の opacity:0）。\n      appearance.js が付けるクラスに当たったものだけ出る。\n\n      絵を数百枚描かずに数百通りにするための重ね方（DESIGN.md §9）：\n      武器 6 型 × 守り 5 型 × 速さ 4 型 = 120、それぞれ位が 5 段（色）、\n      さらに育ちの段が 8 ── 掛け算で桁が上がる。\n\n      **体の輪郭の外に置く**（胴体は x 44〜156、y 78〜166）。重ねると\n      顔と模様が潰れる ── 顔つきは型が決めるものなので、装備で隠さない。\n    -->\n    <g id=\"gear\">\n      <!--\n        手前に残すのは**体に着るもの**だけ ── 胴当ては腹に貼り付くので、\n        奥に回すと丸ごと消える（体の内側にしか無い）。\n      -->\n      <!-- 胴当ては**腹に置く**。胸まで上げると口と目に掛かる ── 顔つきは\n           型が決めるものなので、装備で隠さない（§8c） -->\n      <g class=\"gear-def\" id=\"gw-plate\">\n        <path class=\"plate\" d=\"M66 150 h68 q -4 16 -34 16 q -30 0 -34 -16 Z\" />\n        <path class=\"trim\" d=\"M100 150 v15\" />\n      </g>\n    </g>\n\n    <!--\n      育ちの段。**節目は実績と同じ位置**（Lv30 熟練で角、Lv50 達人で尾…）\n      ── 揃っていないと、どちらも薄くなる。\n    -->\n    <g id=\"growth\">\n      <g class=\"grow\" id=\"lk-horns\">\n        <path d=\"M72 88 l-10 -22 l18 12 Z\" />\n        <path d=\"M128 88 l10 -22 l-18 12 Z\" />\n      </g>\n      <g class=\"grow\" id=\"lk-tail\">\n        <path d=\"M44 148 q -26 6 -30 -14 q -2 -12 10 -12\" />\n      </g>\n      <g class=\"grow\" id=\"lk-halo\">\n        <ellipse cx=\"100\" cy=\"124\" rx=\"84\" ry=\"66\" />\n      </g>\n      <g class=\"grow\" id=\"lk-sigil\">\n        <path d=\"M100 60 l7 12 l14 2 l-10 10 l3 14 l-14 -7 l-14 7 l3 -14 l-10 -10 l14 -2 Z\" />\n      </g>\n    </g>\n\n    <!--\n      スキンの小物。体に付くので creature の中（体と一緒に伸び縮みする）。\n      料理や本と違って「持ち替える」ものではないので、props とは別に置く。\n    -->\n    <g id=\"skin-trinket\">\n      <!-- 熾火：肩口の火の粉 -->\n      <g class=\"trinket\" id=\"trinket-spark\">\n        <circle cx=\"146\" cy=\"98\" r=\"2.6\" />\n        <circle cx=\"153\" cy=\"88\" r=\"1.8\" />\n        <circle cx=\"140\" cy=\"86\" r=\"1.4\" />\n      </g>\n\n      <!-- 霜：白い息 -->\n      <g class=\"trinket\" id=\"trinket-breath\">\n        <ellipse cx=\"128\" cy=\"146\" rx=\"7\" ry=\"4.5\" />\n        <ellipse cx=\"140\" cy=\"142\" rx=\"4.5\" ry=\"3\" />\n        <ellipse cx=\"149\" cy=\"139\" rx=\"2.6\" ry=\"1.8\" />\n      </g>\n\n      <!-- 宵：ついてくる蛾 -->\n      <g class=\"trinket\" id=\"trinket-moth\">\n        <path d=\"M52 92 q -7 -6 -1 -10 q 5 -2 6 5 q 1 -7 6 -5 q 6 4 -1 10 Z\" />\n        <circle cx=\"57\" cy=\"93\" r=\"1.6\" />\n      </g>\n    </g>\n  </g>\n\n  <!--\n    小道具。**既定では全部消えている**（CSS で opacity:0）。\n    暮らしのしぐさ（gestures.js の ACTIVITIES）が #stage にクラスを付けたときだけ、\n    その回に要るものが出る。\n\n    creature の外に置いてあるのは、体のアニメーション（scale/rotate）を\n    小道具まで巻き込まないため ── 巻き込むと、伸びをするたびに丼が伸びる。\n  -->\n  <g id=\"props\">\n    <!-- ハンバーガー。上下のバンズと具 -->\n    <g class=\"prop\" id=\"prop-burger\">\n      <path class=\"bun\" d=\"M138 138 Q 152 126 166 138 Z\" />\n      <rect class=\"patty\" x=\"137\" y=\"139\" width=\"30\" height=\"5\" rx=\"2\" />\n      <rect class=\"leaf\" x=\"136\" y=\"144\" width=\"32\" height=\"4\" rx=\"2\" />\n      <path class=\"bun\" d=\"M137 149 h30 a5 5 0 0 1 -5 5 h-20 a5 5 0 0 1 -5 -5 Z\" />\n    </g>\n\n    <!-- 小籠包。せいろと湯気 -->\n    <g class=\"prop\" id=\"prop-bun\">\n      <g class=\"steam\">\n        <path d=\"M146 128 q 4 -7 0 -14\" />\n        <path d=\"M156 126 q 4 -8 0 -15\" />\n      </g>\n      <circle class=\"dumpling\" cx=\"147\" cy=\"141\" r=\"6\" />\n      <circle class=\"dumpling\" cx=\"159\" cy=\"141\" r=\"6\" />\n      <rect class=\"basket\" x=\"136\" y=\"145\" width=\"32\" height=\"9\" rx=\"3\" />\n    </g>\n\n    <!-- そば。丼と、持ち上げた麺 -->\n    <g class=\"prop\" id=\"prop-soba\">\n      <path class=\"noodle\" d=\"M150 128 q 3 8 -1 14\" />\n      <path class=\"noodle\" d=\"M156 127 q 2 9 -2 15\" />\n      <path class=\"bowl\" d=\"M134 142 h36 a18 18 0 0 1 -36 0 Z\" />\n      <rect class=\"chopsticks\" x=\"150\" y=\"112\" width=\"3\" height=\"22\" rx=\"1.5\" transform=\"rotate(12 151 123)\" />\n      <rect class=\"chopsticks\" x=\"156\" y=\"112\" width=\"3\" height=\"22\" rx=\"1.5\" transform=\"rotate(20 157 123)\" />\n    </g>\n\n    <!-- 映画。四角い画面と、ちらつく光 -->\n    <g class=\"prop\" id=\"prop-movie\">\n      <rect class=\"screen\" x=\"8\" y=\"96\" width=\"46\" height=\"34\" rx=\"4\" />\n      <rect class=\"flicker\" x=\"12\" y=\"100\" width=\"38\" height=\"26\" rx=\"2\" />\n      <rect class=\"stand\" x=\"28\" y=\"130\" width=\"6\" height=\"10\" rx=\"2\" />\n    </g>\n\n    <!-- 本。読んでいるあいだ開いている -->\n    <g class=\"prop\" id=\"prop-book\">\n      <path class=\"page\" d=\"M70 150 q 15 -6 28 0 v18 q -14 -6 -28 0 Z\" />\n      <path class=\"page\" d=\"M102 150 q 14 -6 28 0 v18 q -13 -6 -28 0 Z\" />\n      <path class=\"spine\" d=\"M100 150 v18\" />\n    </g>\n\n    <!-- 金づち。叩いているあいだだけ -->\n    <g class=\"prop\" id=\"prop-hammer\">\n      <rect class=\"handle\" x=\"152\" y=\"118\" width=\"4\" height=\"26\" rx=\"2\" />\n      <rect class=\"head\" x=\"142\" y=\"110\" width=\"24\" height=\"10\" rx=\"3\" />\n    </g>\n\n    <!-- 筆。書いているあいだ -->\n    <g class=\"prop\" id=\"prop-brush\">\n      <rect class=\"handle\" x=\"150\" y=\"112\" width=\"4\" height=\"24\" rx=\"2\" />\n      <path class=\"tip\" d=\"M150 136 h4 l-2 10 Z\" />\n    </g>\n\n    <!-- 望遠鏡。外を見に行くとき -->\n    <g class=\"prop\" id=\"prop-scope\">\n      <rect class=\"tube\" x=\"120\" y=\"96\" width=\"34\" height=\"10\" rx=\"5\" transform=\"rotate(-24 137 101)\" />\n      <circle class=\"lens\" cx=\"152\" cy=\"90\" r=\"6\" />\n    </g>\n\n    <!-- 手紙。任せたとき、飛んでいく -->\n    <g class=\"prop\" id=\"prop-letter\">\n      <rect class=\"paper\" x=\"140\" y=\"96\" width=\"26\" height=\"18\" rx=\"2\" />\n      <path class=\"fold\" d=\"M140 96 l13 10 l13 -10\" />\n    </g>\n\n    <!-- 布団。寝ているあいだ -->\n    <g class=\"prop\" id=\"prop-blanket\">\n      <path class=\"cloth\" d=\"M46 148 q 54 -14 108 0 v10 q -54 12 -108 0 Z\" />\n    </g>\n\n    <!--\n      じゃれてくる相手。**世話をするものではない。**\n\n      餌をやったり撫でたりはさせない（DESIGN.md §3 ── 育成のための操作を\n      足さない）。向こうから来て、しばらく遊んで、勝手に帰る。こちらが\n      できるのは眺めることだけで、それは相棒に対してと同じ扱い。\n    -->\n    <!--\n      ここから 3 匹は**差し替える前提**で置いてある。\n      ─────────────────────────────────────────────\n      絵を描き直すときの決まりは 4 つだけ：\n\n      1. 外側の <g class=\"prop\" id=\"prop-xxx\"> は残す。\n         id が動きの引き金（style.css の #stage.g-cat #prop-cat）。\n      2. 座標はこの 200x200 の中で、**下に書いた枠に収める**。\n         枠を外れると、相棒の体（胴体は x 44〜156）に重なって\n         「頭だけ出たよく分からない生き物」になる ── 実際そうなっていた。\n      3. 色はクラスで付ける。fill/stroke を直に書かない\n         ── 書くとスキンや系統色が効かなくなる。\n         使えるクラス … fur（体）beady（目）whisker（ひげ・脚）\n         tail（しっぽ・振る）wing（翼・羽ばたく）beak（くちばし）\n         shellline（甲羅の筋）foot（足）\n      4. 動く部品には元と同じクラスを付ける。tail と wing と\n         （亀の）fur には CSS 側で動きが付いていて、\n         クラスが無いと**その部品だけ止まる**。\n\n      枠 … 猫 x 140〜200 / y 112〜170   小鳥 x 100〜136 / y 50〜82\n           亀 x 142〜196 / y 148〜170\n\n      SVG 以外（PNG）は貼らないこと。拡大で潰れるうえ、色が変えられない。\n    -->\n    <!--\n      猫。しっぽを振って、じゃれつく。\n    -->\n    <g class=\"prop\" id=\"prop-cat\">\n      <path class=\"tail\" d=\"M182 152 q 15 -2 11 -19\" />\n      <path class=\"fur\" d=\"M158 148 h24 a7 7 0 0 1 7 7 v11 h-38 v-11 a7 7 0 0 1 7 -7 Z\" />\n      <circle class=\"fur\" cx=\"165\" cy=\"136\" r=\"13\" />\n      <path class=\"fur\" d=\"M155 127 l-3 -12 l11 6 Z\" />\n      <path class=\"fur\" d=\"M175 127 l3 -12 l-11 6 Z\" />\n      <circle class=\"beady\" cx=\"160\" cy=\"135\" r=\"2\" />\n      <circle class=\"beady\" cx=\"171\" cy=\"135\" r=\"2\" />\n      <path class=\"whisker\" d=\"M152 140 h-9 M178 140 h9\" />\n    </g>\n\n    <!-- 小鳥。頭にとまる -->\n    <g class=\"prop\" id=\"prop-bird\">\n      <ellipse class=\"fur\" cx=\"112\" cy=\"66\" rx=\"10\" ry=\"8\" />\n      <circle class=\"fur\" cx=\"121\" cy=\"60\" r=\"6\" />\n      <path class=\"beak\" d=\"M126 59 l7 2 l-7 3 Z\" />\n      <circle class=\"beady\" cx=\"122\" cy=\"59\" r=\"1.6\" />\n      <path class=\"wing\" d=\"M108 62 q 8 4 2 9\" />\n      <path class=\"whisker\" d=\"M110 74 v6 M116 74 v6\" />\n    </g>\n\n    <!-- 亀。急がない相手。こちらも輪郭の外（右下）から来る -->\n    <g class=\"prop\" id=\"prop-turtle\">\n      <path class=\"fur\" d=\"M156 160 q 18 -22 36 0 Z\" />\n      <path class=\"shellline\" d=\"M165 156 v-8 M174 152 v-9 M183 156 v-8\" />\n      <circle class=\"fur\" cx=\"152\" cy=\"158\" r=\"7\" />\n      <circle class=\"beady\" cx=\"149\" cy=\"157\" r=\"1.7\" />\n      <path class=\"foot\" d=\"M162 160 v7 M186 160 v7\" />\n    </g>\n\n    <!-- 湯のみ。ひと息ついているとき -->\n    <g class=\"prop\" id=\"prop-tea\">\n      <g class=\"steam\">\n        <path d=\"M150 132 q 4 -7 0 -13\" />\n      </g>\n      <path class=\"cup\" d=\"M140 138 h20 v8 a10 10 0 0 1 -20 0 Z\" />\n    </g>\n  </g>\n</svg>\n`;\n" },
  "gestures.js": { type: "text/javascript; charset=utf-8", body: "/**\n * しぐさ ── 画面に出ている間、ときどき勝手に動く。\n *\n * このアプリで一番長く見ている画面は「何も起きていないオーバーレイ」なので、\n * そこが退屈だと成長を眺める気にならない。逆にここが賑やかなら、戦闘ログを\n * 読み込まなくても「生きている」が伝わる。\n *\n * **選ぶところだけを切り出してある。** 実際の動きは CSS のキーフレームで、\n * 描画は pet.js。ここは「いまの気分でどのしぐさが許されるか」だけを決める\n * 純粋な関数なので、ブラウザ無しでテストできる。\n *\n * ES モジュールにしていないのは pet-svg.js と同じ理由（<script src> で読む）。\n */\n(function (global) {\n  /**\n   * moods … その気分のときだけ出る。weight … 出やすさ。ms … CSS 側の長さと合わせる。\n   *\n   * calling（許可待ち）はどこにも入れていない。返事を待っている子が\n   * のんきに伸びをしたら、見ている側は気づけない。\n   */\n  const GESTURES = [\n    { id: 'look', ms: 1700, weight: 4, moods: ['idle', 'thinking', 'working'] },\n    { id: 'bounce', ms: 1000, weight: 3, moods: ['idle', 'working'] },\n    { id: 'tilt', ms: 1200, weight: 3, moods: ['idle', 'thinking'] },\n    { id: 'stretch', ms: 1300, weight: 3, moods: ['idle'] },\n    { id: 'yawn', ms: 1500, weight: 2, moods: ['idle'] },\n    { id: 'spin', ms: 900, weight: 2, moods: ['idle'] },\n    { id: 'shiver', ms: 700, weight: 1, moods: ['idle', 'sleeping'] },\n    { id: 'roll', ms: 2000, weight: 2, moods: ['sleeping'] },\n\n    // 気分ごとの「らしさ」。同じしぐさが全部の気分に出ると、気分が意味を失う。\n    { id: 'peek', ms: 1600, weight: 3, moods: ['idle', 'thinking'] }, // 画面をのぞきこむ（打っている手元を見にくる）\n    { id: 'ponder', ms: 2200, weight: 4, moods: ['thinking'] }, // 首をひねって考えこむ\n    { id: 'typing', ms: 1400, weight: 4, moods: ['working'] }, // 手が動いている\n    { id: 'dream', ms: 2600, weight: 3, moods: ['sleeping'] }, // 寝ながら浮かぶ\n    { id: 'sneeze', ms: 900, weight: 1, moods: ['idle'] }, // たまに、くしゃみ\n\n    /*\n     * **手が空いているあいだの細かい身振り。**\n     *\n     * 何も起きていない時間がいちばん長いので、ここが薄いと数日で置物に見える。\n     * 小道具を持たないぶん絵を足さずに増やせる ── ただし**全部を大きく動かさない**。\n     * 大きい身振り（跳ねる・つまずく）と、ほとんど動かないもの（集中・ため息）を\n     * 混ぜておかないと、うるさいだけで生き物には見えない。\n     */\n    { id: 'nod', ms: 1300, weight: 3, moods: ['idle', 'thinking'] }, // うなずく\n    { id: 'shake', ms: 1200, weight: 2, moods: ['thinking'] }, // 首を振る（ちがう）\n    { id: 'sway', ms: 2400, weight: 3, moods: ['idle'] }, // 鼻歌まじりに揺れる\n    { id: 'perk', ms: 1800, weight: 3, moods: ['idle', 'thinking'] }, // 何かに気づく\n    { id: 'sigh', ms: 1900, weight: 2, moods: ['idle', 'thinking'] }, // ため息\n    { id: 'wobble', ms: 1400, weight: 2, moods: ['idle'] }, // ぐらついて持ち直す\n    { id: 'stumble', ms: 1500, weight: 1, moods: ['idle'] }, // つまずく\n    { id: 'hop', ms: 1200, weight: 3, moods: ['idle', 'working'] }, // 上機嫌に 2 回跳ねる\n    { id: 'lookback', ms: 1600, weight: 2, moods: ['idle'] }, // 後ろを振り返る\n    { id: 'scratch', ms: 1500, weight: 2, moods: ['idle', 'thinking'] }, // 頭をかく\n    { id: 'focus', ms: 2000, weight: 3, moods: ['working'] }, // 前に出て、止まる\n    { id: 'snore', ms: 2800, weight: 4, moods: ['sleeping'] }, // 寝息\n    { id: 'turnover', ms: 2400, weight: 2, moods: ['sleeping'] }, // 寝返り\n\n    // 戦闘は「たまに思い出したように」。今日の一戦がある日だけ混ざる。\n    { id: 'battle', ms: 3400, weight: 2, moods: ['idle', 'thinking'], needsBattle: true },\n  ];\n\n  /**\n   * 暮らし ── **画面の前にいる間、ずっと何かしている**ためのもの。\n   *\n   * しぐさ（上）が 1〜2 秒の身振りなのに対して、こちらは 4〜7 秒の場面で、\n   * たいてい小道具を持つ（pet-svg.js の #props）。何も起きていない時間が\n   * いちばん長い画面なので、そこが「ただ浮いているだけ」だと数日で飽きる。\n   *\n   * **何をしているかは、その時こちらが何をしているかで変わる。**\n   * キーボードもマウスも覗いていない（覗いた時点でこのアプリの前提が壊れる）。\n   * 見ているのは hook が既に送っている「いまどの道具が動いたか」だけ ──\n   *\n   *   Read / Grep が続く   … あなたは出てきたものを追っている  → 相棒も本を読む\n   *   Bash が動いている     … 走らせて待っている               → 金づちを叩く\n   *   Edit / Write          … 書いている                        → 筆を持つ\n   *   WebSearch / MCP       … 外を見に行っている                → 望遠鏡をのぞく\n   *   Task                  … 任せた                            → 手紙を出す\n   *   指示を打った直後       … **あなたが打っている**            → 何も持たずに待つ\n   *   しばらく動きがない     … 離席・考え中                      → 飯を食う・映画を観る\n   */\n  const ACTIVITIES = [\n    // 手が空いているとき。**ここがいちばん長いので、いちばん賑やか。**\n    { id: 'burger', ms: 5200, weight: 3, moods: ['idle'], prop: 'burger' },\n    { id: 'bun', ms: 5400, weight: 3, moods: ['idle'], prop: 'bun' },\n    { id: 'soba', ms: 5600, weight: 3, moods: ['idle'], prop: 'soba' },\n    { id: 'tea', ms: 4400, weight: 3, moods: ['idle'], prop: 'tea' },\n    { id: 'movie', ms: 7000, weight: 3, moods: ['idle'], prop: 'movie' },\n    { id: 'nap', ms: 6000, weight: 2, moods: ['idle', 'sleeping'], prop: 'blanket' },\n    { id: 'doze', ms: 6600, weight: 3, moods: ['sleeping'], prop: 'blanket' },\n\n    /*\n     * じゃれてくる相手。**世話をするものではない。**\n     *\n     * 餌やりも撫でるボタンも付けない（DESIGN.md §3 ── 育成のための操作を\n     * 足さない）。向こうから来て、しばらく遊んで、勝手に帰る ── こちらが\n     * できるのは眺めることだけで、そこは相棒に対してと同じ扱いにしてある。\n     *\n     * 作業中には出さない。手が止まっているときに来るから「遊んでいる」に\n     * 見えるのであって、打っている最中に猫が来たら、それはただの邪魔になる。\n     */\n    { id: 'cat', ms: 6400, weight: 3, moods: ['idle'], prop: 'cat' },\n    { id: 'bird', ms: 5600, weight: 2, moods: ['idle'], prop: 'bird' },\n    { id: 'turtle', ms: 6800, weight: 2, moods: ['idle'], prop: 'turtle' },\n    // 寝ているところに猫が来て、丸まって一緒に寝る\n    { id: 'catnap', ms: 7000, weight: 3, moods: ['sleeping'], prop: 'cat' },\n\n    // 作業中。**道具ごとに別のことをする**\n    { id: 'reading', ms: 5000, weight: 6, moods: ['working'], tools: ['read'], prop: 'book' },\n    { id: 'hammering', ms: 4200, weight: 6, moods: ['working'], tools: ['run'], prop: 'hammer' },\n    { id: 'carving', ms: 4600, weight: 6, moods: ['working'], tools: ['write'], prop: 'brush' },\n    { id: 'scouting', ms: 4800, weight: 6, moods: ['working'], tools: ['out'], prop: 'scope' },\n    { id: 'sending', ms: 4400, weight: 6, moods: ['working'], tools: ['hand'], prop: 'letter' },\n  ];\n\n  /**\n   * ツール名 → 何をしている場面か。\n   * classes.js の系統と似ているが、こちらは**見た目の担当**なので別に持つ\n   * （系統は 5 つに固定だが、こちらは絵が増えれば増える）。\n   */\n  function sceneForTool(tool) {\n    if (!tool) return null;\n    if (tool.startsWith('mcp__')) return 'out';\n    if (['Read', 'Grep', 'Glob', 'NotebookRead'].includes(tool)) return 'read';\n    if (['Bash', 'BashOutput', 'KillShell'].includes(tool)) return 'run';\n    if (['Write', 'Edit', 'NotebookEdit'].includes(tool)) return 'write';\n    if (['WebSearch', 'WebFetch'].includes(tool)) return 'out';\n    if (['Task', 'Agent', 'Workflow'].includes(tool)) return 'hand';\n    return null;\n  }\n\n  const ALL = () => GESTURES.concat(ACTIVITIES);\n  const BY_ID = new Map();\n\n  /**\n   * 型（persona.js）ごとの、しぐさの出やすさの足し引き。\n   *\n   * **型で出るしぐさを変える。** 同じ動きしかしないなら、型は文字が変わるだけの\n   * 飾りになる ── 「うちの子はよく画面をのぞきこむ」が、そのまま\n   * 「外に出て行くほうの人だから」になっているのが、この機能の値打ち。\n   *\n   * 足すのは重みだけで、**どの気分で何が許されるかは変えない**（寝ている子は\n   * 型が何であれ跳ねない）。\n   */\n  const PERSONA_WEIGHTS = {\n    out: { peek: 3, bounce: 2, spin: 1, bird: 2, perk: 3, lookback: 2 }, // 出て行く ── 外から来たものによく気づく\n    in: { look: 2, ponder: 2, tilt: 1, cat: 1, focus: 2, scratch: 1 }, // 籠る\n    move: { typing: 2, stretch: 2, bounce: 1, hop: 2, stumble: 1 }, // 動かす\n    build: { ponder: 3, tilt: 2, look: 1, nod: 2, focus: 2 }, // 組み立てる\n    cut: { typing: 2, look: 2, nod: 2, shake: 1 }, // 刻む\n    trust: { yawn: 2, spin: 2, sneeze: 1, sway: 2, sigh: 1 }, // 委ねる\n    through: { typing: 1, stretch: 2, look: 1, focus: 2, snore: 1 }, // 走り切る\n    spread: { spin: 2, sneeze: 2, roll: 1, wobble: 2, lookback: 1 }, // 散らす\n    calm: { stretch: 1, dream: 1, turtle: 2, sway: 2, snore: 2 }, // 凪 ── 急がない相手と気が合う\n    wave: { bounce: 1, sneeze: 1, cat: 2, hop: 2, wobble: 1 }, // 波 ── じゃれるほうが合う\n  };\n\n  /**\n   * その型で、そのしぐさがどれだけ出やすいか。\n   * marks は persona.js が返す印の配列（['in','build','cut','through','calm']）。\n   */\n  function weightFor(gesture, marks) {\n    let weight = gesture.weight;\n    if (!Array.isArray(marks)) return weight;\n    for (const mark of marks) {\n      const table = PERSONA_WEIGHTS[mark];\n      if (table && table[gesture.id]) weight += table[gesture.id];\n    }\n    return weight;\n  }\n\n  /**\n   * 次までの間。**空ける時間を短くした** ── 5〜15 秒あけていた頃は、\n   * 眺めていると「止まっている置物」の時間のほうが長かった。\n   * 等間隔にはしない（途端に機械に見える）。\n   */\n  function nextDelay(rng) {\n    return 700 + rng() * 2600;\n  }\n\n  /**\n   * いまの気分で出せるしぐさを 1 つ選ぶ。出せるものが無ければ null。\n   *\n   * rng を引数で受けるのは、テストで固定するため。\n   */\n  function pick(mood, options, rng) {\n    const hasBattle = Boolean(options && options.hasBattle);\n    const persona = options && options.persona;\n    const scene = sceneForTool(options && options.tool);\n\n    const pool = ALL().filter((g) => {\n      if (!g.moods.includes(mood)) return false;\n      if (g.needsBattle && !hasBattle) return false;\n      // 道具が決まっている場面は、いまその道具が動いているときだけ\n      if (g.tools && !g.tools.includes(scene)) return false;\n      return true;\n    });\n    if (!pool.length) return null;\n\n    const weights = pool.map((g) => weightFor(g, persona));\n    let total = 0;\n    for (const w of weights) total += w;\n\n    let roll = rng() * total;\n    for (let i = 0; i < pool.length; i += 1) {\n      roll -= weights[i];\n      if (roll < 0) return pool[i];\n    }\n    return pool[pool.length - 1];\n  }\n\n  function byId(id) {\n    if (!BY_ID.size) for (const g of ALL()) BY_ID.set(g.id, g);\n    return BY_ID.get(id) || null;\n  }\n\n  global.AIPET_GESTURES = { GESTURES, ACTIVITIES, PERSONA_WEIGHTS, sceneForTool, pick, nextDelay, byId, weightFor };\n})(typeof window !== 'undefined' ? window : globalThis);\n" },
  "mobile.js": { type: "text/javascript; charset=utf-8", body: "/* スマホ用の読み取り専用ダッシュボード。/api/state を叩いて描くだけ。 */\n\ndocument.getElementById('pet-mount').innerHTML = window.AIPET_SVG;\n\nconst stage = document.getElementById('stage');\nconst title = document.getElementById('title');\nconst subtitle = document.getElementById('subtitle');\nconst meterFill = document.getElementById('meter-fill');\nconst meterInto = document.getElementById('meter-into');\nconst meterNext = document.getElementById('meter-next');\nconst dailyExp = document.getElementById('daily-exp');\nconst moodEl = document.getElementById('mood');\nconst traitsEl = document.getElementById('traits');\nconst skillsEl = document.getElementById('skills');\nconst achievementsEl = document.getElementById('achievements');\nconst achievementCount = document.getElementById('achievement-count');\nconst jobsEl = document.getElementById('jobs');\nconst jobsNote = document.getElementById('jobs-note');\nconst battlePanel = document.getElementById('battle-panel');\nconst battleHead = document.getElementById('battle-head');\nconst battleResult = document.getElementById('battle-result');\nconst battleLog = document.getElementById('battle-log');\nconst battleNote = document.getElementById('battle-note');\nconst battleImpression = document.getElementById('battle-impression');\nconst expeditionPanel = document.getElementById('expedition-panel');\nconst expeditionHead = document.getElementById('expedition-head');\nconst findsEl = document.getElementById('finds');\nconst barsEl = document.getElementById('bars');\nconst trailEl = document.getElementById('trail');\nconst trailTotal = document.getElementById('trail-total');\nconst trailNote = document.getElementById('trail-note');\nconst personaCode = document.getElementById('persona-code');\nconst personaName = document.getElementById('persona-name');\nconst personaBlurb = document.getElementById('persona-blurb');\nconst personaAxes = document.getElementById('persona-axes');\nconst personaNote = document.getElementById('persona-note');\nconst chasingEl = document.getElementById('chasing');\nconst ratesEl = document.getElementById('rates');\nconst hexGrid = document.getElementById('hex-grid');\nconst hexShape = document.getElementById('hex-shape');\nconst hexLabels = document.getElementById('hex-labels');\nconst hexRows = document.getElementById('hex-rows');\nconst dungeonPanel = document.getElementById('dungeon-panel');\nconst dungeonFloor = document.getElementById('dungeon-floor');\nconst gearEl = document.getElementById('dungeon-gear');\nconst dungeonFinds = document.getElementById('dungeon-finds');\nconst bossesEl = document.getElementById('bosses');\nconst bossesNote = document.getElementById('bosses-note');\nconst menuButton = document.getElementById('menu-open');\nconst drawer = document.getElementById('drawer');\nconst scrim = document.getElementById('scrim');\nconst drawerList = document.getElementById('drawer-list');\nconst recapPanel = document.getElementById('recap-panel');\nconst recapSpan = document.getElementById('recap-span');\nconst recapRows = document.getElementById('recap-rows');\nconst recapNote = document.getElementById('recap-note');\nconst drawerName = document.getElementById('drawer-name');\nconst drawerLevel = document.getElementById('drawer-level');\n\nconst MOODS = ['idle', 'working', 'thinking', 'calling', 'sleeping'];\n\n/** スキンの id。付け替えのときに前のクラスを外すためだけに持つ。 */\nconst SKIN_IDS = ['plain', 'mono', 'ember', 'frost', 'dusk'];\n\n/** 表示する traits と、その並び順。0 のものは出さない（育つほど行が増える）。 */\nconst TRAIT_KEYS = ['toolCalls', 'prompts', 'sessions', 'comebacks', 'failures', 'compacts', 'nightOwl'];\n\n/*\n * **この画面に日本語（や英語）を書かない。** 文言はすべて view.text から引く\n * ── ここで文を組むと、同じ文がオーバーレイと 2 通りに育つ（src/core/i18n.js）。\n */\nlet TEXT = {};\nlet LANG = 'ja';\n\nconst say = (id) => TEXT[id] || '';\n\n/** 動かない文字（見出し・ラベル）を、view が解いてきた言語に差し替える。 */\nfunction applyText(view) {\n  TEXT = view.text || {};\n  LANG = view.lang || 'ja';\n  for (const el of document.querySelectorAll('[data-t]')) {\n    const value = TEXT[el.dataset.t];\n    if (value) el.textContent = value;\n  }\n  document.documentElement.lang = LANG;\n}\n\n/**\n * 名前・値・注記の 1 行。\n *\n * **注記を必ず置けるようにする。** 「つまずいた割合 0%」「受けた指示 95」は、\n * 数字だけ出しても何を数えたのか読めない ── 根拠を出すのがこのアプリの芯\n * （DESIGN.md §8c）なので、行のほうに注記の場所を作っておく。\n */\nfunction noteRow(label, value, note, sub) {\n  const row = document.createElement('div');\n  row.className = note || sub ? 'row has-note' : 'row';\n  row.innerHTML = '<span></span><b></b>';\n  row.firstChild.textContent = label;\n  row.lastChild.textContent = value;\n  if (sub) {\n    const em = document.createElement('em');\n    em.className = 'row-sub';\n    em.textContent = sub;\n    row.appendChild(em);\n  }\n  if (note) {\n    const small = document.createElement('small');\n    small.className = 'row-note';\n    small.textContent = note;\n    row.appendChild(small);\n  }\n  return row;\n}\n\n/** 桁区切り。見ている言語に合わせる。 */\nfunction num(value) {\n  return Number(value || 0).toLocaleString(LANG === 'ja' ? 'ja-JP' : 'en-US');\n}\n\n/**\n * 「8月10日」/「Aug 10」。年は出さない（この画面に出るのは直近だけ）。\n *\n * **日付だけは端末側で作る。** サーバー（Worker）のローカルは UTC なので、\n * 向こうで文字にすると日付の変わり目に 1 日ずれる（src/core/clock.js と同じ話）。\n */\nfunction fmtDay(at) {\n  const d = new Date(at);\n  return LANG === 'ja'\n    ? `${d.getMonth() + 1}月${d.getDate()}日`\n    : d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });\n}\n\n/** view が `{day}` を空けて渡してきた文に、端末の暦で日付を入れる。 */\nfunction withDay(line, at) {\n  return line && at ? line.replace('{day}', fmtDay(at)) : line;\n}\n\n/* ------------------------------------------------------------------ *\n * 目次（左カラム）\n *\n * 節が 11 個まで増えて、縦スクロールだけでは端から端まで遠くなった。\n * **中身は隠さない** ── ここは飛ぶための目次で、節を畳んだり切り替えたり\n * はしない（隠すと「そこに何があるか」が消える）。\n * ------------------------------------------------------------------ */\nfunction buildDrawer() {\n  if (drawerList.children.length) return;\n  let group = null;\n  for (const section of document.querySelectorAll('[data-sec]')) {\n    /*\n     * **本文と同じ切れ目を目次にも入れる。** 11 行が同じ見た目で並んでいると、\n     * 目次のほうが本文より読みにくくなる ── ページの束（data-group）を\n     * そのまま持ち込めば、探す前に「どのあたりか」で当たりが付く。\n     */\n    if (section.dataset.group && section.dataset.group !== group) {\n      group = section.dataset.group;\n      const head = document.createElement('li');\n      head.className = 'drawer-group';\n      head.dataset.group = group;\n      drawerList.appendChild(head);\n    }\n    const item = document.createElement('li');\n    const link = document.createElement('a');\n    link.href = `#${section.dataset.sec}`;\n    link.dataset.sec = section.dataset.sec;\n    section.id = section.id || section.dataset.sec;\n    link.addEventListener('click', (event) => {\n      event.preventDefault();\n      closeDrawer();\n      section.scrollIntoView({ behavior: 'smooth', block: 'start' });\n    });\n    item.appendChild(link);\n    drawerList.appendChild(item);\n  }\n}\n\nfunction openDrawer() {\n  drawer.classList.add('open');\n  drawer.setAttribute('aria-hidden', 'false');\n  menuButton.setAttribute('aria-expanded', 'true');\n  scrim.hidden = false;\n}\n\nfunction closeDrawer() {\n  drawer.classList.remove('open');\n  drawer.setAttribute('aria-hidden', 'true');\n  menuButton.setAttribute('aria-expanded', 'false');\n  scrim.hidden = true;\n}\n\nmenuButton.addEventListener('click', () => {\n  if (drawer.classList.contains('open')) closeDrawer();\n  else openDrawer();\n});\nscrim.addEventListener('click', closeDrawer);\ndocument.addEventListener('keydown', (event) => {\n  if (event.key === 'Escape') closeDrawer();\n});\n\n/** 見出しの文字は view.text から。目次にも同じものを出す。 */\nfunction labelDrawer(view) {\n  buildDrawer();\n  drawerName.textContent = view.name;\n  drawerLevel.textContent = `Lv${view.level}`;\n  for (const link of drawerList.querySelectorAll('a')) {\n    link.textContent = say(`panel.${link.dataset.sec}`) || link.dataset.sec;\n  }\n  for (const head of drawerList.querySelectorAll('.drawer-group')) {\n    head.textContent = say(`group.${head.dataset.group}`) || head.dataset.group;\n  }\n}\n\n/* ------------------------------------------------------------------ *\n * しぐさ\n *\n * **オーバーレイと同じものを使う**（shared/gestures.js）。スマホ用に別の\n * 動きを書くと、同じ子が 2 通りの動き方をすることになる。\n *\n * 見ていない間は動かさない ── 電池を使うだけで、誰も見ていない。\n * ------------------------------------------------------------------ */\nlet gesture = null;\nlet gestureTimer = null;\n\nfunction playGesture(id, ms) {\n  const def = window.AIPET_GESTURES.byId(id);\n  const duration = ms || (def ? def.ms : 1000);\n  if (gesture) stage.classList.remove(`g-${gesture}`);\n  gesture = id;\n  stage.classList.add(`g-${id}`);\n  setTimeout(() => {\n    if (gesture !== id) return;\n    stage.classList.remove(`g-${id}`);\n    gesture = null;\n  }, duration);\n}\n\nfunction scheduleGesture() {\n  clearTimeout(gestureTimer);\n  const delay = window.AIPET_GESTURES.nextDelay(Math.random);\n  gestureTimer = setTimeout(() => {\n    if (!document.hidden && current && !gesture) {\n      const def = window.AIPET_GESTURES.pick(\n        current.mood,\n        {\n          hasBattle: Boolean(current.battle),\n          persona: current.persona && current.persona.marks,\n          tool: current.lastTool,\n        },\n        Math.random,\n      );\n      // 戦闘のしぐさは、勝った日と負けた日で別のものにする\n      if (def && def.id === 'battle') {\n        playGesture(current.battle.winner === 'foe' ? 'battle-lose' : 'battle-win', 3400);\n      } else if (def) {\n        playGesture(def.id);\n      }\n    }\n    scheduleGesture();\n  }, delay);\n}\n\n/** いま出ている view。しぐさの選び方がこれを見る。 */\nlet current = null;\n\n/*\n * **1 つの節が転けても、後ろを道連れにしない。**\n *\n * 前は 9 つの描画をそのまま順に呼んでいたので、`renderHexagon` の中で\n * 例外が出ると、そこから後ろ（迷宮・技・一戦・称号…）が丸ごと描かれずに\n * 終わっていた ── しかも**画面には見出しだけが残る**ので、壊れているのか\n * 中身が無いのかが見分けられない。実際 iPhone でそうなっていた。\n *\n * 節ごとに囲って、転けた節にはその場で理由を出す。**黙って消えるのがいちばん困る。**\n */\nfunction section(key, fn, view) {\n  try {\n    fn(view);\n  } catch (error) {\n    const panel = document.querySelector(`[data-sec=\"${key}\"]`);\n    if (!panel) return;\n    let note = panel.querySelector('.panel-error');\n    if (!note) {\n      note = document.createElement('p');\n      note.className = 'panel-error';\n      panel.appendChild(note);\n    }\n    note.textContent = `${error && error.message ? error.message : error}`;\n  }\n}\n\nfunction render(view) {\n  current = view;\n  applyText(view);\n  labelDrawer(view);\n  for (const mood of MOODS) stage.classList.toggle(`mood-${mood}`, view.mood === mood);\n\n  // キャラ（#stage）とページ全体（:root）の両方に系統色を流す\n  const hue = view.hue ?? 220;\n  const sat = view.hue === null || view.hue === undefined ? '12%' : '58%';\n  for (const el of [stage, document.documentElement]) {\n    el.style.setProperty('--hue', String(hue));\n    el.style.setProperty('--sat', sat);\n  }\n\n  // 大きさも appearance.js が出す ── **Lv13 で頭打ちだったのを Lv500 まで伸ばした**\n  const scale = (view.look && view.look.scale) || Math.min(1.12, 0.82 + view.level * 0.024);\n  stage.style.setProperty('--scale', scale.toFixed(3));\n\n  // 型（persona.js）を顔つきに落とす。4 文字ぶんのクラスを付けるだけで、\n  // 実際の差は style.css 側にある ── **型が字面だけにならないように**、\n  // 目つきと口元がその人の使い方で変わる。\n  for (const mark of ['in', 'out', 'move', 'build', 'cut', 'trust', 'through', 'spread']) {\n    stage.classList.remove(`p-${mark}`);\n  }\n  for (const mark of ['calm', 'wave']) stage.classList.remove(`r-${mark}`);\n  if (view.persona && view.persona.settled) {\n    for (const mark of view.persona.marks) {\n      // リズムだけは息づかいの速さ（r-）。ほかは顔つき（p-）\n      stage.classList.add(mark === 'calm' || mark === 'wave' ? `r-${mark}` : `p-${mark}`);\n    }\n  }\n\n  /*\n   * 見た目の重ね着。**ここで条件を書かない** ── どの層を出すかは\n   * appearance.js が決めて、クラス名だけ渡ってくる（view.look.marks）。\n   * 書くと、オーバーレイとスマホで別々の見た目に育つ。\n   *\n   * 前に付いていたぶんを全部外してから付け直す ── 装備は潜るたびに変わるので、\n   * 外し忘れると剣と斧を同時に持つ。\n   *\n   * **ac-（小物）・pt-（使い込み）・hurt-（ケガ）も必ず外す。** 前は lk-/gw-/gr-\n   * だけを外していて、ケガが 1 時間で治らずに付きっぱなしになっていた\n   * ── 消える側の印は、外し忘れると永久に消えない。\n   */\n  const look = view.look || { marks: [], scale: null };\n  for (const cls of [...stage.classList]) {\n    if (/^(lk-|gw-|gr-|ac-|pt-|hurt-)/.test(cls)) stage.classList.remove(cls);\n  }\n  for (const mark of look.marks) stage.classList.add(mark);\n\n  /*\n   * 空の色。**時刻はここで読まない** ── view.js が tzOffset ごと解いて渡す\n   * （機械のローカルを見ると、PC とスマホで別の空になる）。\n   */\n  for (const sky of ['dawn', 'day', 'dusk', 'night']) stage.classList.remove(`sky-${sky}`);\n  if (view.sky) stage.classList.add(`sky-${view.sky}`);\n  // 昔の名前も残しておく（気分・しぐさ側の指定がこれを見ている）\n  stage.classList.toggle('has-antenna', view.level >= 3);\n  stage.classList.toggle('has-crown', view.level >= 10);\n  stage.classList.toggle('has-aura', view.level >= 15);\n\n  /*\n   * スキン（skins.js）。**クラスを 1 つ付け替えるだけ。**\n   * 色も模様も小物も CSS 側にあるので、ここで見た目の中身は決めない\n   * ── 決めると、オーバーレイとスマホで別々の見た目に育つ。\n   */\n  for (const id of SKIN_IDS) stage.classList.remove(`skin-${id}`);\n  if (view.skin) stage.classList.add(`skin-${view.skin.id}`);\n\n  // 全角の空きは日本語のときだけ。英語に混ぜると、そこだけ間が抜けて見える\n  const gap = LANG === 'ja' ? '　' : ' ';\n  title.textContent = view.name ? `${view.name}${gap}Lv${view.level}` : `Lv${view.level}`;\n  // 名前の下は**その名前の中身**。系統（学者・職人…）は色と相性に効くので\n  // 「働き方」の節に置いてあり、ここでは肩書きを 2 つ並べない。\n  const persona = view.persona;\n  subtitle.textContent = persona && persona.settled\n    ? persona.rhythmSettled\n      ? `${persona.blurb} ── ${persona.rhythmBlurb}`\n      : persona.blurb\n    : say('persona.hint');\n\n  meterFill.style.width = `${Math.round(view.ratio * 100)}%`;\n  meterInto.textContent = say('level.into');\n  meterNext.textContent = say('level.next');\n\n  dailyExp.textContent = say('exp.today');\n  moodEl.textContent = say('mood.now');\n\n  traitsEl.innerHTML = '';\n  for (const key of TRAIT_KEYS) {\n    const value = view.traits?.[key] || 0;\n    if (!value) continue;\n    // 数え方を隣に書く。**「受けた指示 95」だけでは何を数えたのか読めない**\n    traitsEl.appendChild(noteRow(say(`trait.${key}`), num(value), say(`note.${key}`)));\n  }\n  if (!traitsEl.children.length) {\n    const row = document.createElement('div');\n    row.className = 'row';\n    row.innerHTML = '<span></span><b>─</b>';\n    row.firstChild.textContent = say('trait.none');\n    traitsEl.appendChild(row);\n  }\n\n  section('trail', renderTrail, view);\n  section('name', renderPersona, view);\n  section('hexagon', renderHexagon, view);\n  section('dungeon', renderDungeon, view);\n  section('skills', renderSkills, view);\n  section('battle', renderBattle, view);\n  section('achievements', renderAchievements, view);\n  section('expedition', renderExpedition, view);\n  section('style', renderProfile, view);\n  section('recap', renderRecap, view);\n\n  // タブに出るのは**この子の名前**（＝いまの職）。Maite はプロダクトの名前なので出さない\n  document.title = `${view.name} Lv${view.level}`;\n\n  maybeShowBattle();\n}\n\n/**\n * **開いたら、その一戦を 1 回だけ見せる。**\n *\n * 戦闘は「読むログ」ではなく「たまに見かけるしぐさ」に降ろしてある（DESIGN.md §5c）。\n * オーバーレイは一日中そこに出ているので、その確率で足りる ── ところが\n * **スマホは見ようとして開くもの**で、開いている 20 秒ほどのあいだに\n * しぐさの抽選が当たるとは限らない。同じ設計をそのまま持ってきた結果、\n * **スマホでは戦っているところをほとんど見られなかった**（2026-08-16 の指摘）。\n *\n * だから開いた 1 回につき 1 回だけ、自分から流す。\n *\n * - **ボタンは足さない。** 押すものを増やすと「見に行く作業」になる\n * - **繰り返さない。** 1 回で終わり。もう一度見たければ開き直すだけ\n * - **隠れているあいだは流さない**（誰も見ていない画面で終わってしまう）\n */\nlet battleShown = false;\n\nfunction maybeShowBattle() {\n  if (battleShown || gesture || !current || !current.battle) return;\n  if (document.hidden) return;\n  battleShown = true;\n  // 開いた直後は画面が組み上がっている最中なので、少し置いてから\n  setTimeout(() => {\n    if (!current || !current.battle) return;\n    if (document.hidden) {\n      // 見ていないあいだに終わらせない。次に描いたときに出す\n      battleShown = false;\n      return;\n    }\n    playGesture(current.battle.winner === 'foe' ? 'battle-lose' : 'battle-win', 3400);\n  }, 900);\n}\n\n/**\n * 型 ── 「どう使っているか」から出た性格。\n *\n * **根拠を必ず一緒に出す。** 「あなたは○○型です」だけだと占いになる。\n * 何を見てそう言っているか（調べものの割合、1 指示で動く回数）が横にあると、\n * 外れていても「そら そう見えるわな」で終われるし、当たっていれば効く。\n *\n * 一番下の但し書きも消さないこと ── 中身を読んでいないから面白いのであって、\n * 読んで当てているなら、それはただの盗み見になる。\n */\nfunction renderPersona(view) {\n  const persona = view.persona;\n  personaAxes.innerHTML = '';\n  if (!persona) return;\n\n  const settled = persona.settled;\n  // 読みだけ小さく添える。名前は読めないと呼べない（英語では読みが要らない）\n  personaCode.textContent = settled && LANG === 'ja' ? persona.yomi : '';\n  personaName.textContent = settled ? persona.title : say('persona.unsettled');\n\n  // 「いつから今の名前か」「前は何だったか」。**知らない間に変わっていたことに、\n  // 後から気づけるように。** 変わったのは働き方が変わったからで、それが下の軸に出ている。\n  personaBlurb.textContent = withDay(persona.line, persona.since);\n\n  for (const axis of persona.axes) {\n    const row = document.createElement('div');\n    row.className = 'axis';\n    if (!axis.known) row.classList.add('unknown');\n    // 5 軸目（リズム）は 4 文字の後ろに付くぶん。区切りを入れて別物に見せる\n    if (axis.suffix) row.classList.add('suffix');\n\n    const left = document.createElement('b');\n    left.textContent = axis.left.label;\n    left.className = axis.code === axis.left.code ? 'on' : '';\n\n    const meter = document.createElement('i');\n    const dot = document.createElement('span');\n    // 目盛りの上の位置。真ん中が境目で、端に寄るほどその傾向が強い\n    dot.style.left = `${Math.round(axis.position * 100)}%`;\n    meter.appendChild(dot);\n\n    const right = document.createElement('b');\n    right.textContent = axis.right.label;\n    right.className = axis.code === axis.right.code ? 'on' : '';\n\n    /*\n     * **寄っているほうの意味を先に、根拠を後に。**「籠る」だけでは何のことか\n     * 分からないが、「手元を読んで、自分で叩く」が並べば読める。根拠（何を見て\n     * そう言っているか）は消さない ── 無いと占いになる（DESIGN.md §8c）。\n     */\n    const meaning = document.createElement('u');\n    meaning.className = 'axis-meaning';\n    meaning.textContent = axis.meaning || '';\n\n    const from = document.createElement('em');\n    from.textContent = axis.from;\n\n    row.append(left, meter, right, meaning, from);\n    personaAxes.appendChild(row);\n  }\n\n  // この但し書きは消さない ── 中身を読んでいないから面白いのであって、\n  // 読んで当てているなら、それはただの盗み見になる\n  personaNote.textContent = say('persona.note');\n}\n\n/**\n * ここ 2 週間の働き方を、1 日 1 本の柱で出す。\n *\n * **数字ではなく形で見るためのもの。** 「今日 240 EXP」だけだと、それが多いのか\n * 少ないのか分からない ── 隣に先週が並んで初めて「今週は失速した」が読める。\n * 働かなかった日は空のまま置く（詰めると休んだ日が無かったことになる）。\n */\nfunction renderTrail(view) {\n  const trail = view.trail || [];\n  trailEl.innerHTML = '';\n  // 合計と一言（乗ってきた / 失速した）は view.js が組んである\n  trailTotal.textContent = say('exp.trail');\n  trailNote.textContent = say('trail.note');\n  if (!trail.length) return;\n\n  const today = trail[trail.length - 1].day;\n  for (const entry of trail) {\n    const cell = document.createElement('div');\n    cell.className = 'trail-day';\n    if (entry.day === today) cell.classList.add('is-today');\n    if (!entry.exp) cell.classList.add('is-empty');\n    cell.title = `${entry.day} · ${num(entry.exp)} EXP`;\n\n    const bar = document.createElement('i');\n    // 0 の日も 2px だけ残す ── 完全に消すと、休んだ日が列から抜けて見える\n    bar.style.height = `${Math.round(6 + entry.ratio * 54)}px`;\n    const label = document.createElement('em');\n    label.textContent = entry.day.slice(-2).replace(/^0/, '');\n\n    cell.append(bar, label);\n    trailEl.appendChild(cell);\n  }\n}\n\n/**\n * 渡り歩いた職。**なった順（古い順）に並べる ── 道として読む。**\n *\n * **まだなっていない職は出さない。** 出した瞬間に「16 個集める」チェックリストに\n * なり、集めるために働き方を変える話になる（DESIGN.md §5b）。\n * ここにあるのは「そういえば あの頃は罠師だった」だけ。\n */\nfunction renderJobs(view) {\n  const jobs = view.jobs || [];\n  jobsEl.innerHTML = '';\n  if (!jobs.length) {\n    jobsNote.textContent = '';\n    return;\n  }\n\n  jobsNote.textContent = `${say('jobs.count')} · ${say('jobs.note')}`;\n  for (const job of jobs) {\n    const chip = document.createElement('span');\n    chip.className = 'job';\n    // 「鍛冶師になった」から「になった」を落として、職の名前だけ並べる\n    chip.textContent = job.label.replace(/になった$/, '').replace(/^Became an? /, '');\n    chip.title = `${fmtDay(job.at)} · ${job.blurb}`;\n    /*\n     * **その職としての位。** 全体が Lv10 でも、錬金術師としては Lv3 のことがある\n     * ── どの道をどれだけ歩いたかが、ここに出る。\n     */\n    const lv = document.createElement('u');\n    lv.className = 'job-level';\n    lv.textContent = job.levelText || '';\n    const when = document.createElement('em');\n    when.textContent = fmtDay(job.at);\n    chip.append(lv, when);\n    jobsEl.appendChild(chip);\n  }\n}\n\n/** 獲った日付が入るので、獲得済みは新しい順。まだのものは薄く下に並べる。 */\nfunction renderAchievements(view) {\n  renderJobs(view);\n  const got = view.achievements || [];\n  const left = view.achievementsLocked || [];\n  achievementCount.textContent = say('achievement.count');\n\n  /*\n   * **獲ったものは畳んでおく。** 26 個ぜんぶを説明つきで縦に並べると、それだけで\n   * 画面の半分が称号になる（「実績も長すぎる」）。名前と日付だけを 2 列で敷いて、\n   * **読みたいものだけ開く**（<details> なので、指 1 本で開いて勝手に閉じない）。\n   *\n   * まだのものは名前だけ、薄く、まとめて 1 か所に。説明も進捗も付けない\n   * ── 付けた瞬間に集めに行くチェックリストになる（DESIGN.md §5b）。\n   */\n  achievementsEl.innerHTML = '';\n  for (const item of got) {\n    const row = document.createElement('details');\n    row.className = item.rough ? 'achievement rough' : 'achievement';\n    const head = document.createElement('summary');\n    head.innerHTML = '<b></b><time></time>';\n    head.children[0].textContent = item.label;\n    head.children[1].textContent = fmtDay(item.at);\n    const why = document.createElement('span');\n    why.textContent = item.blurb;\n    row.append(head, why);\n    achievementsEl.appendChild(row);\n  }\n\n  if (left.length) {\n    const rest = document.createElement('p');\n    rest.className = 'achievement-rest';\n    rest.textContent = `${say('badge.locked')} ── ${left.map((item) => item.label).join('・')}`;\n    achievementsEl.appendChild(rest);\n  }\n}\n\n/* ------------------------------------------------------------------ *\n * 六角形の能力値\n *\n * **上がったところは緑、下がったところは赤**を数秒だけ出す。\n * 数字が並んでいるだけだと、どこが動いたのか眺めていても分からない\n * ── 動いた頂点だけ光れば、見た瞬間に「速さが伸びた」が読める。\n *\n * 前回の値は画面の中だけで覚える（保存しない）。開き直せば消えるが、\n * ここで見たいのは「見ている間に何が動いたか」なので、それでいい。\n * ------------------------------------------------------------------ */\nconst HEX_R = 62;\nconst HEX_CX = 100;\nconst HEX_CY = 88;\n/** 光らせておく時間。長いと、ずっと光っている画面になる。 */\nconst HEX_FLASH_MS = 6000;\n\nconst hexSeen = new Map();\nconst hexFlash = new Map();\n\nfunction hexPoint(index, radius) {\n  const angle = ((-90 + index * 60) * Math.PI) / 180;\n  return [HEX_CX + Math.cos(angle) * radius, HEX_CY + Math.sin(angle) * radius];\n}\n\nfunction hexPolygon(scale) {\n  const points = [];\n  for (let i = 0; i < 6; i += 1) {\n    const [x, y] = hexPoint(i, HEX_R * scale);\n    points.push(`${x.toFixed(1)},${y.toFixed(1)}`);\n  }\n  return points.join(' ');\n}\n\n/** 子を全部外す。HTML でも SVG でも同じに効く（innerHTML は SVG で効かない）。 */\nfunction clear(el) {\n  while (el.firstChild) el.removeChild(el.firstChild);\n}\n\nfunction svg(tag, attrs) {\n  const el = document.createElementNS('http://www.w3.org/2000/svg', tag);\n  for (const [key, value] of Object.entries(attrs)) el.setAttribute(key, value);\n  return el;\n}\n\n/** 目盛りの輪。真ん中の輪（0.56）が「同じレベルの平均」。 */\nfunction drawHexGrid() {\n  if (hexGrid.childNodes.length) return;\n  for (const scale of [1, 0.78, 0.56, 0.32]) {\n    hexGrid.appendChild(\n      svg('polygon', { class: scale === 0.56 ? 'hex-ring is-average' : 'hex-ring', points: hexPolygon(scale) }),\n    );\n  }\n  for (let i = 0; i < 6; i += 1) {\n    const [x, y] = hexPoint(i, HEX_R);\n    hexGrid.appendChild(\n      svg('line', { class: 'hex-spoke', x1: HEX_CX, y1: HEX_CY, x2: x.toFixed(1), y2: y.toFixed(1) }),\n    );\n  }\n}\n\nfunction renderHexagon(view) {\n  const axes = view.hexagon || [];\n  if (!axes.length) return;\n  drawHexGrid();\n\n  const now = Date.now();\n  const points = [];\n  /*\n   * **SVG の中身は innerHTML で消さない。**\n   *\n   * `innerHTML` は仕様上 Element に生えているが、WebKit は SVG 要素で\n   * 実装していない ── iPhone だけ「見出しは出るのに中身が空」になっていた原因。\n   * DOM で外せばどのブラウザでも同じに動く。\n   */\n  clear(hexLabels);\n  hexRows.innerHTML = '';\n\n  axes.forEach((axis, i) => {\n    const [x, y] = hexPoint(i, HEX_R * axis.ratio);\n    points.push(`${x.toFixed(1)},${y.toFixed(1)}`);\n\n    // 前に見たときから動いたか。初回は覚えるだけで光らせない\n    const before = hexSeen.get(axis.id);\n    if (before !== undefined && before !== axis.value) {\n      hexFlash.set(axis.id, { dir: axis.value > before ? 'up' : 'down', until: now + HEX_FLASH_MS });\n    }\n    hexSeen.set(axis.id, axis.value);\n    const flash = hexFlash.get(axis.id);\n    const moved = flash && flash.until > now ? flash.dir : '';\n\n    // 頂点の外に 1 文字。長い名前を置くと図が潰れる\n    const [lx, ly] = hexPoint(i, HEX_R + 17);\n    const text = svg('text', {\n      class: `hex-label ${moved}`.trim(),\n      x: lx.toFixed(1),\n      y: (ly + 4).toFixed(1),\n      'text-anchor': 'middle',\n    });\n    text.textContent = axis.label;\n    hexLabels.appendChild(text);\n\n    /*\n     * 図の頂点は 1 文字でないと潰れるが、**行のほうは読んで分かる名前**にする。\n     * 値の下に「平均の 1.3 倍」を添える ── 「攻撃 45」だけでは、強いのか\n     * 弱いのかが読めない。\n     */\n    const row = noteRow(axis.fullLabel || axis.label, num(axis.value), axis.note, axis.multText);\n    if (moved) row.classList.add(moved);\n    hexRows.appendChild(row);\n  });\n\n  hexShape.setAttribute('points', points.join(' '));\n}\n\n/**\n * ダンジョン ── 潜った深さと、勝手に着いた装備。\n *\n * **選ばせない。** 拾ったものを並べて選ばせると「良いものを狙って潜る」が\n * 生まれて、普段どおり仕事をするだけでよくなくなる（DESIGN.md §3）。\n */\nfunction renderDungeon(view) {\n  const dungeon = view.dungeon;\n  if (!dungeon) return;\n\n  dungeonFloor.textContent = dungeon.floorText;\n\n  gearEl.innerHTML = '';\n  for (const item of dungeon.equipped) {\n    const row = document.createElement('div');\n    row.className = `gear-item r-${item.rarity}`;\n    row.innerHTML = '<i></i><b></b><em></em><span></span>';\n    row.children[0].textContent = say(`hex.${item.slot}`);\n    row.children[1].textContent = item.label;\n    row.children[2].textContent = item.rarityLabel;\n    // 枠をまたいで乗るぶんまで出す（「攻 +14% 速 +4%」）── 宿りで形が変わるのが\n    // ここに見えないと、宿りは名前だけの飾りになる\n    row.children[3].textContent = item.weight.map((w) => `${say(`hex.${w.slot}`)}+${w.percent}%`).join(' ');\n    gearEl.appendChild(row);\n\n    // 宿り。**効果まで必ず出す** ── 隠すと、外の攻略サイトで調べる遊びになる\n    for (const imbue of item.imbues) {\n      const line = document.createElement('div');\n      line.className = 'imbue';\n      line.innerHTML = '<b></b><span></span>';\n      line.children[0].textContent = imbue.label;\n      line.children[1].textContent = imbue.blurb;\n      gearEl.appendChild(line);\n    }\n  }\n\n  /*\n   * 抜けてきた主。**新しい順**（いま どこにいるかから読む）。\n   * まだ会っていない主は出さない ── 出した瞬間に「12 体そろえる」の話になる。\n   */\n  const bosses = dungeon.bosses || [];\n  bossesNote.hidden = !bosses.length;\n  bossesEl.innerHTML = '';\n  for (const boss of bosses) {\n    const row = document.createElement('div');\n    row.className = 'boss';\n    row.innerHTML = '<i></i><b></b><span></span>';\n    row.children[0].textContent = String(boss.floor);\n    row.children[1].textContent = boss.label;\n    row.children[2].textContent = boss.blurb;\n    bossesEl.appendChild(row);\n  }\n\n  dungeonFinds.innerHTML = '';\n  for (const item of dungeon.recent) {\n    // 位はクラスで渡すだけ。色は CSS 側（灰→緑→青→紫→金）\n    const chip = document.createElement('span');\n    chip.className = `find r-${item.rarity}`;\n    chip.textContent = item.label;\n    chip.title = `${item.rarityLabel} · ${item.percent}%`;\n    const at = document.createElement('em');\n    at.textContent = String(item.floor);\n    chip.appendChild(at);\n    dungeonFinds.appendChild(chip);\n  }\n}\n\n/** 生えたスキルと、まだ生えていないものの「何をすれば生えるか」。 */\nfunction renderSkills(view) {\n  skillsEl.innerHTML = '';\n\n  for (const skill of view.skills || []) {\n    skillsEl.appendChild(skillRow(skill, false));\n  }\n  for (const hint of view.skillHints || []) {\n    skillsEl.appendChild(skillRow(hint, true));\n  }\n}\n\n/**\n * 「あと N 回」は技にだけ出す。何をすればこの子の形が変わるかは見えていい。\n * 実績には出さない（出した瞬間、振り返るものから狙うものになる）。\n */\nfunction skillRow(skill, locked) {\n  const row = document.createElement('div');\n  row.className = locked ? 'skill locked' : 'skill';\n  row.innerHTML = '<b></b><i></i><em></em><span></span>';\n  row.children[0].textContent = skill.label;\n  row.children[1].textContent = skill.tier ? '★'.repeat(skill.tier) : '─';\n  row.children[2].textContent = skill.remainingText || '';\n  /*\n   * **生えた技には、効き目を数字で出す。**「素早さが上がる」だけでは本当に\n   * 効いているのか確かめようがない ── この数字は battle.js が実際に使うものと\n   * 同じ出どころ（skills.js の SKILL_POWER）。\n   *\n   * 説明文（blurb）は出さない。「夜の戦いで攻撃と素早さが上がる」と\n   * 「未明の一戦だけ、攻撃と素早さ +6%」が並ぶと、同じことを 2 度読まされる。\n   * まだ生えていない技は、効き目より**何をすれば生えるか**のほうが要る。\n   */\n  const effect = !locked && skill.effectText;\n  row.children[3].textContent = locked ? skill.from : skill.effectText || skill.blurb;\n  if (effect) row.children[3].className = 'is-effect';\n  return row;\n}\n\n/** 合計値だけでは「何をしていたか」が読めないので、内訳と比率を出す。 */\nfunction renderProfile(view) {\n  const profile = view.profile;\n  if (!profile) return;\n\n  barsEl.innerHTML = '';\n  for (const entry of profile.breakdown) {\n    const row = document.createElement('div');\n    row.className = 'bar';\n    row.innerHTML = '<b></b><i><span></span></i><em></em>';\n    row.children[0].textContent = entry.label;\n    row.children[1].firstChild.style.width = `${Math.round(entry.share * 100)}%`;\n    row.children[1].firstChild.style.background = `hsl(${entry.hue} 58% 58%)`;\n    row.children[2].textContent = `${Math.round(entry.share * 100)}%`;\n    barsEl.appendChild(row);\n  }\n  if (!profile.breakdown.length) {\n    barsEl.textContent = say('style.none');\n  }\n\n  // 「開発スタイルが変われば見た目も変わる」の目安\n  chasingEl.textContent = profile.chasing ? profile.chasing.text : '';\n\n  ratesEl.innerHTML = '';\n  for (const entry of profile.rows || []) {\n    ratesEl.appendChild(noteRow(entry.label, entry.value, entry.note));\n  }\n}\n\n/** 留守中の土産。強さには一切関係しない（DESIGN.md §5）。 */\nfunction renderExpedition(view) {\n  const trip = view.expedition;\n  expeditionPanel.hidden = !trip;\n  if (!trip) return;\n\n  expeditionHead.textContent = trip.head;\n\n  clear(findsEl);\n  for (const find of trip.finds) {\n    // 名前と、相棒の観察記録。**一言のほうが本体**（view.js の注記）\n    const row = document.createElement('div');\n    row.className = find.rare ? 'find rare' : 'find';\n    const name = document.createElement('b');\n    name.textContent = find.label;\n    row.appendChild(name);\n    if (find.note) {\n      const note = document.createElement('small');\n      note.textContent = find.note;\n      row.appendChild(note);\n    }\n    findsEl.appendChild(row);\n  }\n}\n\n/**\n * ひと月のふりかえり。**後ろ向きにしか出さない**（core/recap.js）── 目安も\n * 次の目標も前月との勝ち負けも無い。手を動かした日が 5 日に満たないうちは\n * view が null を返すので、節ごと出ない。\n */\nfunction renderRecap(view) {\n  const recap = view.recap;\n  recapPanel.hidden = !recap;\n  if (!recap) return;\n  recapSpan.textContent = recap.span;\n  recapNote.textContent = recap.note;\n  clear(recapRows);\n  for (const row of recap.rows) recapRows.appendChild(noteRow(row.label, row.value));\n}\n\nfunction renderBattle(view) {\n  const battle = view.battle;\n\n  if (!battle) {\n    battleHead.textContent = say('battle.locked');\n    battleResult.textContent = '';\n    battleResult.className = 'battle-result';\n    battleImpression.textContent = '';\n    battleLog.innerHTML = '';\n    battleNote.textContent = '';\n    battlePanel.classList.add('empty');\n    return;\n  }\n\n  battlePanel.classList.remove('empty');\n  // 相手のレベルは出さない。「あと何レベルで勝てる」が分かると、その日が終わる\n  battleHead.textContent = battle.head;\n  battleResult.textContent = battle.result;\n  battleResult.className = `battle-result ${battle.winner}`;\n  battleImpression.textContent = battle.impression || '';\n\n  battleLog.innerHTML = '';\n  for (const line of battle.lines) {\n    const li = document.createElement('li');\n    li.textContent = line;\n    battleLog.appendChild(li);\n  }\n\n  // 練習相手であることは必ず出す。黙ると信用が飛ぶ。\n  // 「2 時間ごとに一戦」も添える ── 次を待てばいいと分かると、負けた回で終わらない\n  battleNote.textContent = [battle.note, say('battle.every')].filter(Boolean).join(' · ');\n}\n\n/**\n * 同じ Wi-Fi の PC が配信している場合はトークン無し。\n * サーバー版は推測不能 URL がそのまま鍵なので、それを問い合わせに乗せる。\n */\n// 問い合わせるときのことば。**返ってきた view.lang（LANG）とは別物**\n// ── こちらは希望で、実際に何語で返ってきたかはサーバーが決める\nconst ASK_LANG = new URLSearchParams(location.search).get('lang') || navigator.language || 'ja';\n// ことばは「URL の ?lang= → ブラウザ」。サーバー側は、送られてきた設定も見る\nconst API = window.AIPET_TOKEN\n  ? `/api/state?token=${encodeURIComponent(window.AIPET_TOKEN)}&lang=${encodeURIComponent(ASK_LANG)}`\n  : `/api/state?lang=${encodeURIComponent(ASK_LANG)}`;\n\n/*\n * 聞きに行く間隔。**3 秒ごとに叩いていて、それでサーバーを落とした。**\n *\n * 1 回の読みで KV の `list` が 3 回走っていたので、**1 分あたり 60 回**。\n * KV の 1 日ぶんの `list` と `write` はどちらも 1,000 なので、\n * **画面を 20 分開いていればその日ぶんを使い切る** ── 使い切ると\n * `list` が投げて `/api/state` も `/ingest` も 500 に落ち、\n * **スマホから何も見えなくなる。** 実際にそうなった。\n *\n * ここで守るのは 3 つ：\n *\n * 1. **隠れている間は聞きに行かない。** 見ていない画面のために叩かない\n * 2. **変わらなければ間隔を空ける**（15 秒 → 最大 10 分）。開きっぱなしで\n *    忘れられたページが、1 日ぶんを使い切らない量に収まる ── **変わったら\n *    15 秒に戻る**ので、見ている最中に鈍くなることはない\n * 3. **変わったら、また詰める。** 見ている最中の反応は鈍らせない\n *\n * 育つのは分単位の話なので、15 秒でも十分すぎる（3 秒は、ただの無駄だった）。\n */\nconst POLL_MIN_MS = 15000;\nconst POLL_MAX_MS = 600000;\nconst POLL_BACKOFF = 1.5;\n\nlet pollWait = POLL_MIN_MS;\nlet pollTimer = null;\nlet lastSeenStamp = null;\n\n/** 中身が変わったか。**畳んだ結果の要点だけ**を見る（全体を比べると重い）。 */\nfunction stampOf(view) {\n  return [view.exp, view.level, view.mood, view.lastTool, view.dungeon && view.dungeon.floor].join('|');\n}\n\nasync function poll() {\n  try {\n    const res = await fetch(API, { cache: 'no-store' });\n    if (!res.ok) throw new Error(String(res.status));\n    const view = await res.json();\n    const stamp = stampOf(view);\n    // 変わっていなければ少しずつ間隔を空ける。変わったら詰め直す\n    pollWait = stamp === lastSeenStamp ? Math.min(POLL_MAX_MS, pollWait * POLL_BACKOFF) : POLL_MIN_MS;\n    lastSeenStamp = stamp;\n    render(view);\n    document.body.classList.remove('stale');\n  } catch {\n    // PC が寝た / Wi-Fi が切れた。古い数字を黙って出し続けない。\n    // **叩き続けない** ── 落ちている相手を 3 秒ごとに突くのがいちばん良くない\n    pollWait = Math.min(POLL_MAX_MS, pollWait * POLL_BACKOFF);\n    document.body.classList.add('stale');\n  }\n  schedulePoll();\n}\n\nfunction schedulePoll() {\n  clearTimeout(pollTimer);\n  // 隠れている間は止める。戻ってきたときに聞き直す\n  if (document.hidden) return;\n  pollTimer = setTimeout(poll, pollWait);\n}\n\npoll();\nscheduleGesture();\n// 画面を戻したときは待たずに取り直す（間隔も詰め直す）\ndocument.addEventListener('visibilitychange', () => {\n  if (document.hidden) {\n    clearTimeout(pollTimer);\n    return;\n  }\n  pollWait = POLL_MIN_MS;\n  poll();\n});\n" },
};

/** 素材の中身から出した印。URL に付けて、古いキャッシュに当たらないようにする。 */
export const ASSET_STAMP = "1oilgid";
